INSERT OR IGNORE INTO videos (id,title,description,thumbnail,category,channel,channel_title,channel_id,badge,published_at,city,country,raw_json,active) VALUES ('fqm2KA7MmhA','Alsancak: Vibrant Streets & Cozy Evening Vibes | Izmir, Türkiye 4K Walk','Experience the ultimate Izmir walking tour in 4K! Explore Alsancak, the beating heart of Izmir nightlife and culture, during its most vibrant evening hours. This immersive 4K 60fps walk captures the city''s iconic streets, cozy cafes, and authentic local social life as the day turns into a lively night. If you are looking for an authentic Izmir travel vlog or a relaxing urban exploration with natural ambient city sounds (no narration), this video takes you straight into the soul of Turkey''s most modern city. We stroll through the bustling Kıbrıs Şehitleri Avenue and drift into Alsancak''s vibrant backstreets, where lively pubs, boutique cafes, and historic architecture create a unique atmosphere. Witness the incredible urban contrast as we move from these narrow, lively alleys to the vast, open space of the legendary Kordon coastline. Watch how Izmir locals enjoy the golden hour, relaxing on the grass, catching the sea breeze, and soaking in the sunset. Perfect for fans of 4K virtual walks, travel to Turkey, and relaxing city ambiances. • Location: Alsancak, Izmir, Turkey 🇹🇷 Still walking... 👣 continue walking here: 👉https://www.youtube.com/playlist?list=PLe0tLqhfoJ0lD4ABpCnNmKAxMpHq607gz Contact: izmirexplorer@gmail.com #izmir #alsancak #walkingtour #izmir4k #turkeytravel #kordon','https://i.ytimg.com/vi/fqm2KA7MmhA/maxresdefault.jpg','Night & Rain','Still Walking','Still Walking','UCD9clPtpOTsz7PPrm2JpafQ','4K 60FPS','2024-08-03T12:30:06Z','Izmir','Turkey','{"id":"fqm2KA7MmhA","title":"Alsancak: Vibrant Streets & Cozy Evening Vibes | Izmir, Türkiye 4K Walk","description":"Experience the ultimate Izmir walking tour in 4K! Explore Alsancak, the beating heart of Izmir nightlife and culture, during its most vibrant evening hours. This immersive 4K 60fps walk captures the city''s iconic streets, cozy cafes, and authentic local social life as the day turns into a lively night. If you are looking for an authentic Izmir travel vlog or a relaxing urban exploration with natural ambient city sounds (no narration), this video takes you straight into the soul of Turkey''s most modern city. We stroll through the bustling Kıbrıs Şehitleri Avenue and drift into Alsancak''s vibrant backstreets, where lively pubs, boutique cafes, and historic architecture create a unique atmosphere. Witness the incredible urban contrast as we move from these narrow, lively alleys to the vast, open space of the legendary Kordon coastline. Watch how Izmir locals enjoy the golden hour, relaxing on the grass, catching the sea breeze, and soaking in the sunset. Perfect for fans of 4K virtual walks, travel to Turkey, and relaxing city ambiances. • Location: Alsancak, Izmir, Turkey 🇹🇷 Still walking... 👣 continue walking here: 👉https://www.youtube.com/playlist?list=PLe0tLqhfoJ0lD4ABpCnNmKAxMpHq607gz Contact: izmirexplorer@gmail.com #izmir #alsancak #walkingtour #izmir4k #turkeytravel #kordon","thumbnail":"https://i.ytimg.com/vi/fqm2KA7MmhA/maxresdefault.jpg","category":"Night & Rain","city":"Izmir","country":"Turkey","channel":"Still Walking","channelTitle":"Still Walking","channelId":"UCD9clPtpOTsz7PPrm2JpafQ","badge":"4K 60FPS","publishedAt":"2024-08-03T12:30:06Z","viewCount":143972,"durationSeconds":1852,"admission":{"version":3,"status":"channel-candidate","source":"channel-archive","mode":"CITY"}}','1');
INSERT OR IGNORE INTO videos (id,title,description,thumbnail,category,channel,channel_title,channel_id,badge,published_at,city,country,raw_json,active) VALUES ('b5Dvkk-AEtg','Time Flows Slowly in Foça, İzmir: Historic Streets and Seaside Life | Turkey 4K Walk','A slow walk through Eski Foça on a warm summer day, where nothing feels rushed and time moves a little slower. Historic stone streets, fresh sea air, peaceful footsteps, and the quiet rhythm of the Aegean. This walk takes you through many sides of Foça: the narrow backstreets lined with traditional stone houses, the lively town center, the fisherman’s harbor, the seaside promenade, and the beaches where daily life unfolds under the summer sun. Along the way, you''ll pass the old castle walls, watch people swimming in the clear waters below, and wander through the peaceful Lovers'' Road stretching out over the sea. No talking. No narration. Just real-time walking, natural ambient sounds, and the relaxed atmosphere of one of the Aegean coast''s most beloved seaside towns. still walking 👣 continue walking here: 👉https://www.youtube.com/playlist?list=PLe0tLqhfoJ0lD4ABpCnNmKAxMpHq607gz Contact: izmirexplorer@gmail.com #izmir #foça #walkingtour #turkeytravel #summerwalk','https://i.ytimg.com/vi/b5Dvkk-AEtg/maxresdefault.jpg','Beach Walking Tours','Still Walking','Still Walking','UCD9clPtpOTsz7PPrm2JpafQ','4K 60FPS','2023-06-24T14:01:22Z','Izmir','Turkey','{"id":"b5Dvkk-AEtg","title":"Time Flows Slowly in Foça, İzmir: Historic Streets and Seaside Life | Turkey 4K Walk","description":"A slow walk through Eski Foça on a warm summer day, where nothing feels rushed and time moves a little slower. Historic stone streets, fresh sea air, peaceful footsteps, and the quiet rhythm of the Aegean. This walk takes you through many sides of Foça: the narrow backstreets lined with traditional stone houses, the lively town center, the fisherman’s harbor, the seaside promenade, and the beaches where daily life unfolds under the summer sun. Along the way, you''ll pass the old castle walls, watch people swimming in the clear waters below, and wander through the peaceful Lovers'' Road stretching out over the sea. No talking. No narration. Just real-time walking, natural ambient sounds, and the relaxed atmosphere of one of the Aegean coast''s most beloved seaside towns. still walking 👣 continue walking here: 👉https://www.youtube.com/playlist?list=PLe0tLqhfoJ0lD4ABpCnNmKAxMpHq607gz Contact: izmirexplorer@gmail.com #izmir #foça #walkingtour #turkeytravel #summerwalk","thumbnail":"https://i.ytimg.com/vi/b5Dvkk-AEtg/maxresdefault.jpg","category":"Beach Walking Tours","city":"Izmir","country":"Turkey","channel":"Still Walking","channelTitle":"Still Walking","channelId":"UCD9clPtpOTsz7PPrm2JpafQ","badge":"4K 60FPS","publishedAt":"2023-06-24T14:01:22Z","viewCount":133259,"durationSeconds":2531,"admission":{"version":3,"status":"channel-candidate","source":"channel-archive","mode":"CITY"}}','1');
