INSERT OR IGNORE INTO videos (id,title,description,thumbnail,category,channel,channel_title,channel_id,badge,published_at,city,country,raw_json,active) VALUES ('ZNcha8JlVx8','An Evening That Slowly Comes Alive in İzmir: Kordon & Alsancak | Turkey 4K Walk','An evening walk through İzmir as the city slowly comes alive. Starting at sunset along Kordon, this walk captures people relaxing on the grass, enjoying the sea breeze, and watching the day fade over the waterfront. As evening settles in, we move deeper into Alsancak''s busy streets and narrow back alleys. Cafés fill up, bar streets become livelier, and the atmosphere gradually shifts from a calm summer evening into the vibrant rhythm of the city at night. Along the way you''ll experience different sides of İzmir: the waterfront, bustling avenues, hidden side streets, local nightlife, and the everyday energy that makes Alsancak one of the city''s most loved districts. No talking. No narration. Just real-time walking, natural sounds, and an authentic summer evening in İzmir. still walking 👣 continue walking here: 👉https://www.youtube.com/playlist?list=PLe0tLqhfoJ0lD4ABpCnNmKAxMpHq607gz Contact: izmirexplorer@gmail.com #izmir #alsancak #walkingtour #summertravel #turkeytravel #citywalk #kordon','https://i.ytimg.com/vi/ZNcha8JlVx8/maxresdefault.jpg','Night & Rain','Still Walking','Still Walking','UCD9clPtpOTsz7PPrm2JpafQ','4K 60FPS','2023-07-06T16:00:31Z','Izmir','Turkey','{"id":"ZNcha8JlVx8","title":"An Evening That Slowly Comes Alive in İzmir: Kordon & Alsancak | Turkey 4K Walk","description":"An evening walk through İzmir as the city slowly comes alive. Starting at sunset along Kordon, this walk captures people relaxing on the grass, enjoying the sea breeze, and watching the day fade over the waterfront. As evening settles in, we move deeper into Alsancak''s busy streets and narrow back alleys. Cafés fill up, bar streets become livelier, and the atmosphere gradually shifts from a calm summer evening into the vibra