INSERT OR IGNORE INTO videos (id,title,description,thumbnail,category,channel,channel_title,channel_id,badge,published_at,city,country,raw_json,active) VALUES ('Hyxjbu1O1sg','The Huge Contrast of Izmir: Buca''s Crowded City Center & Silent Old Town | Türkiye 4K Walk 👣','Experience the incredible urban contrast of Turkey with this immersive Izmir Buca walking tour in 4K. This real-time, continuous video follows a unique route that transitions between two completely different worlds. We begin our journey amidst the crowded streets, modern rhythm, and intense movement of Buca’s bustling city center, before everything suddenly slows down. As we follow the natural shift in pace, the noise and pressure of contemporary city life fade away, welcoming you into the quieter corners, older houses, and a completely different rhythm of Izmir''s historic old town. This silent walking video is a raw exploration of authentic local life and architecture, where a classic pink car marks the exact turning point between the modern rush and the nostalgic past. If you are looking for an authentic Izmir walking tour or a deep dive into historical Levantine houses, traditional Greek architecture, and forgotten mansions, this journey captures a side of the city rarely seen by tourists. Filmed with high-quality ambient sounds and no narration, this Buca Izmir street walk offers a relaxing virtual travel experience. Perfect for viewers who enjoy atmospheric walking in Izmir Turkey 4K, urban exploration, and the peaceful, slow-paced atmosphere of hidden historical districts. 📍 Location: Buca, Izmir, Turkey Still walking... 👣 continue walking here: 👉https://www.youtube.com/playlist?list=PLe0tLqhfoJ0lD4ABpCnNmKAxMpHq607gz Contact: izmirexplorer@gmail.com #izmir #buca #walkingtour #streetwalk #turkeytravel #oldtown','https://i.ytimg.com/vi/Hyxjbu1O1sg/maxresdefault.jpg','Museums & Culture','Still Walking','Still Walking','UCD9clPtpOTsz7PPrm2JpafQ','4K 60FPS','2023-05-10T12:00:16Z','Izmir','Turkey',