INSERT OR IGNORE INTO videos (id,title,description,thumbnail,category,channel,channel_title,channel_id,badge,published_at,city,country,raw_json,active) VALUES ('XuY6013l5-0','Alaçatı Comes Alive After Dark... | İzmir 4K Walk','Alaçatı comes alive after dark. As the sun disappears, the narrow stone streets fill with people, restaurants overflow onto the sidewalks, music echoes through the town, and one of Türkiye''s most iconic summer destinations reveals a completely different atmosphere. This real-time 4K walking tour explores both sides of Alaçatı at night. From lively streets packed with visitors to quiet back alleys hidden just a few steps away, every turn offers a different perspective of this beautiful Aegean town. Filmed with natural ambient sounds only—no narration, no music, and no interruptions—this walk captures Alaçatı exactly as it feels on a busy summer night. 📍 Location Alaçatı, Çeşme, İzmir, Türkiye 🎧 Natural Ambient Sounds 🚶 Real-Time Walking Tour 📷 4K City Walk still walking 👣 continue walking here: 👉https://www.youtube.com/playlist?list=PLe0tLqhfoJ0lD4ABpCnNmKAxMpHq607gz Contact: izmirexplorer@gmail.com #Alaçatı #İzmir #Çeşme #Turkey #4KWalk','https://i.ytimg.com/vi/XuY6013l5-0/maxresdefault.jpg','Night & Rain','Still Walking','Still Walking','UCD9clPtpOTsz7PPrm2JpafQ','4K 60FPS','2023-08-02T17:00:10Z','Izmir','Turkey','{"id":"XuY6013l5-0","title":"Alaçatı Comes Alive After Dark... | İzmir 4K Walk","description":"Alaçatı comes alive after dark. As the sun disappears, the narrow stone streets fill with people, restaurants overflow onto the sidewalks, music echoes through the town, and one of Türkiye''s most iconic summer destinations reveals a completely different atmosphere. This real-time 4K walking tour explores both sides of Alaçatı at night. From lively streets packed with visitors to quiet back alleys hidden just a few steps away, every turn offers a different perspective of this beautiful Aegean town. Filmed with natural ambient sounds only—