INSERT OR IGNORE INTO videos (id,title,description,thumbnail,category,channel,channel_title,channel_id,badge,published_at,city,country,raw_json,active) VALUES ('dUvAR9fFKAw','Izmir, Turkey: Walk Around Bornova Streets | Izmir Walking Tour 2023 ( 4K 60fps)','Hi everyone! Today, we''re going on a walking tour of Bornova district. We''ll start our walk at Küçükpark, a lively area with lots of students, and then head towards the beautiful Özkanlar neighborhood. We''ll end our walk at Bölge metro station. Küçükpark and its surroundings are a great place to spend time. There are many cafes, restaurants, and bars to choose from. Do you want to take a night walk in and around Bornova Küçükpark? If so, click on this link for a virtual tour! https://youtu.be/m4St0w809js İzmir walking tour Bornova district June 3, 2023 4 pm saturday Temperature: +24 ℃ Contact: izmirexplorer@gmail.com #izmir #turkey #walkingtour İzmir BORNOVA Sokakları - 4K Bornova Turu - Bornova Küçükpark / Özkanlar','https://i.ytimg.com/vi/dUvAR9fFKAw/maxresdefault.jpg','Walking Tours','Still Walking','Still Walking','UCD9clPtpOTsz7PPrm2JpafQ','4K 60FPS','2023-06-05T15:45:02Z','Izmir','Turkey','{"id":"dUvAR9fFKAw","title":"Izmir, Turkey: Walk Around Bornova Streets | Izmir Walking Tour 2023 ( 4K 60fps)","description":"Hi everyone! Today, we''re going on a walking tour of Bornova district. We''ll start our walk at Küçükpark, a lively area with lots of students, and then head towards the beautiful Özkanlar neighborhood. We''ll end our walk at Bölge metro station. Küçükpark and its surroundings are a great place to spend time. There are many cafes, restaurants, and bars to choose from. Do you want to take a night walk in and around Bornova Küçükpark? If so, click on this link for a virtual tour! https://youtu.be/m4St0w809js İzmir walking tour Bornova district June 3, 2023 4 pm saturday Temperature: +24 ℃ Contact: izmirexplorer@gmail.com #izmir #turkey #walkingtour İzmir BORNOVA Sokakları - 4K Bornova Turu - Bornova Küçükpark / Özkanlar","thumbnail":"https://i.ytimg.com/vi/dUvAR9fFKAw/maxresdefault.jpg","category":"Walking Tours","city":"Izmir","country":"Turkey","channel":"Still Walking","channelTitle":"Still Walking","channelId":"UCD9clPtpOTsz7PPrm2JpafQ","badge":"4K 60FPS","publishedAt":"2023-06-05T15:45:02Z","viewCount":32317,"durationSeconds":3681,"admission":{"version":3,"status":"channel-candidate","source":"channel-archive","mode":"CITY"}}','1');
INSERT OR IGNORE INTO videos (id,title,description,thumbnail,category,channel,channel_title,channel_id,badge,published_at,city,country,raw_json,active) VALUES ('_AywAC9sbXw','A Walking Tour of Yeni Foça: A Perfect Day Trip from Izmir in 4K | Summer 2023','A Walking Tour of Yeni Foça: A Perfect Day Trip from Izmir Bored in the City? Take the Suburban Metro to Yeni Foça for a Day of Fun in the Sun Yeni Foça is a charming seaside town located just an hour from Izmir by suburban metro. With its clear blue waters, delicious seafood restaurants, and lively bars, Yeni Foça is the perfect place to escape the hustle and bustle of the city. After arriving at the Yeni Foça train station, take a short transfer bus ride to the town center. From there, you can spend the day swimming, sunbathing, and exploring the town''s many historical and cultural attractions. In the evening, enjoy a delicious meal at one of Yeni Foça''s many waterfront restaurants. Then, head to one of the town''s lively bars for a nightcap. The last train back to Izmir leaves at 12am, but be sure to allow some extra time for the transfer bus. İzmir walking tour Foça district July 1, 2023 6 pm saturday Temperature: +34 ℃ Contact: izmirexplorer@gmail.com #izmir #turkey #walkingtour','https://i.ytimg.com/vi/_AywAC9sbXw/maxresdefault.jpg','Walking Tours','Still Walking','Still Walking','UCD9clPtpOTsz7PPrm2JpafQ','4K 60FPS','2023-07-02T12:00:37Z','Izmir','Turkey','{"id":"_AywAC9sbXw","title":"A Walking Tour of Yeni Foça: A Perfect Day Trip from Izmir in 4K | Summer 2023","description":"A Walking Tour of Yeni Foça: A Perfect Day Trip from Izmir Bored in the City? Take the Suburban Metro to Yeni Foça for a Day of Fun in the Sun Yeni Foça is a charming seaside town located just an hour from Izmir by suburban metro. With its clear blue waters, delicious seafood restaurants, and lively bars, Yeni Foça is the perfect place to escape the hustle and bustle of the city. After arriving at the Yeni Foça train station, take a