INSERT OR IGNORE INTO videos (id,title,description,thumbnail,category,channel,channel_title,channel_id,badge,published_at,city,country,raw_json,active) VALUES ('l5h2ykKAC9M','Izmir Alsancak Christmas Night Walk: Magical Lights & Cozy Festive Streets 4K 🇹🇷 (2025)','Experience the magical Christmas atmosphere in Alsancak, Izmir! 🇹🇷 This stunning 4K night walking tour captures festive lights, beautifully decorated cafes & bars, vibrant Christmas market vibes, and lively cozy pedestrian streets full of people enjoying the holiday spirit. First 20 minutes: Dive into the heart of Christmas magic with dazzling Noel decorations on bars/cafes and the bustling market. Then, stroll through illuminated, traffic-free avenues packed with cozy restaurants, crowds, and that warm, home-like New Year''s energy in Izmir''s most vibrant neighborhood. Natural sounds only (no commentary) – perfect for virtual holiday travel, relaxation, or planning your festive trip to Turkey! Filmed in crystal-clear 4K for immersive holiday vibes. 📍 Alsancak, Izmir, Turkey | December 2025 00:00 Intro & Magical Christmas Vibes in Alsancak 🎄✨ 01:37 Plevne Bulvarı – Festive Lights Begin 🌟 05:15 Stunning Decorated Cafes & Bars (Pure Christmas Magic!) 🥂🎅 09:50 Immersive Christmas Market Experience 🛍️🎄 15:13 Lively Cozy Pedestrian Streets – Night Glow & Holiday Cheer 🌃✨ 37:20 Surprise Hidden Back Street – Unexpected Cozy Cafe Gem & Relaxing Finale 🌙🇹🇷✨ 🎧 Relaxing ASMR walk – no talking, pure ambient sounds! Izmir Walking Tour🚶‍♂️ Konak District🏛️ Alsancak Neighborhood 🏘️ Date: December 17, 2025 (Wednesday) 📅 Time: 8 PM 🕓 Temperature: 13°C 🌡️ Camera: Dji Osmo Pocket 3 🎥 All Izmir walking tours here: Real Izmir Walking Tours 4K 🇹🇷 https://www.youtube.com/playlist?list=PLe0tLqhfoJ0kA5DZ-hMOT5mX-rHSVN8EK Contact: izmirexplorer@gmail.com #IzmirAlsancak #AlsancakChristmas #ChristmasInIzmir #IzmirChristmas #AlsancakNoel #IzmirNoelPazarı #Yılbasıİzmir #AlsancakNightWalk #IzmirYılbasıIşıkları #ChristmasLightsTurkey #FestiveIzmir #Izmir4K #TurkeyChristmas #NewYearIzmir #AlsancakLights','https://i.ytimg.com/vi/l5h2ykKAC9M/maxresdefault.jpg','Night & Rain','Still Walking','Still Walking','UCD9clPtpOTsz7PPrm2JpafQ','4K 60FPS','2025-12-19T16:30:21Z','Izmir','Turkey','{"id":"l5h2ykKAC9M","title":"Izmir Alsancak Christmas Night Walk: Magical Lights & Cozy Festive Streets 4K 🇹🇷 (2025)","description":"Experience the magical Christmas atmosphere in Alsancak, Izmir! 🇹🇷 This stunning 4K night walking tour captures festive lights, beautifully decorated cafes & bars, vibrant Christmas market vibes, and lively cozy pedestrian streets full of people enjoying the holiday spirit. First 20 minutes: Dive into the heart of Christmas magic with dazzling Noel decorations on bars/cafes and the bustling market. Then, stroll through illuminated, traffic-free avenues packed with cozy restaurants, crowds, and that warm, home-like New Year''s energy in Izmir''s most vibrant neighborhood. Natural sounds only (no commentary) – perfect for virtual holiday travel, relaxation, or planning your festive trip to Turkey! Filmed in crystal-clear 4K for immersive holiday vibes. 📍 Alsancak, Izmir, Turkey | December 2025 00:00 Intro & Magical Christmas Vibes in Alsancak 🎄✨ 01:37 Plevne Bulvarı – Festive Lights Begin 🌟 05:15 Stunning Decorated Cafes & Bars (Pure Christmas Magic!) 🥂🎅 09:50 Immersive Christmas Market Experience 🛍️🎄 15:13 Lively Cozy Pedestrian Streets – Night Glow & Holiday Cheer 🌃✨ 37:20 Surprise Hidden Back Street – Unexpected Cozy Cafe Gem & Relaxing Finale 🌙🇹🇷✨ 🎧 Relaxing ASMR walk – no talking, pure ambient sounds! Izmir Walking Tour🚶‍♂️ Konak District🏛️ Alsancak Neighborhood 🏘️ Date: December 17, 2025 (Wednesday) 📅 Time: 8 PM 🕓 Temperature: 13°C 🌡️ Camera: Dji Osmo Pocket 3 🎥 All Izmir walking tours here: Real Izmir Walking Tours 4K 🇹🇷 https://www.youtube.com/playlist?list=PLe0tLqhfoJ0kA5DZ-hMOT5mX-rHSVN8EK Contact: izmirexplorer@gmail.com #IzmirAlsancak #AlsancakChristmas #ChristmasInIzmir #IzmirChr