INSERT OR IGNORE INTO videos (id,title,description,thumbnail,category,channel,channel_title,channel_id,badge,published_at,city,country,raw_json,active) VALUES ('_x0d_50wiUg','Basmane Area in Izmır: Do Most of the Refugees in Izmir Live Here? | Walking Tour Turkey 4K 60fps','If you''re interested in experiencing Izmir in a different way, then this is the perfect tour for you! During this walk, you will see the city from a unique perspective. You will also have an idea about the living spaces of refugees. Basmane area has been hosting refugees for centuries. After our walk in Basmane, we will pass through the streets of the historical Kemeraltı bazaar and go to Çankaya area. İzmir walking Tour Konak district March 7, 2023 3 pm Tuesday Temperature: +16 ℃ Contact: izmirexplorer@gmail.com #izmir #turkey #walk #walkingtour','https://i.ytimg.com/vi/_x0d_50wiUg/maxresdefault.jpg','Walking Tours','Still Walking','Still Walking','UCD9clPtpOTsz7PPrm2JpafQ','4K 60FPS','2023-03-09T14:00:37Z','Izmir','Turkey','{"id":"_x0d_50wiUg","title":"Basmane Area in Izmır: Do Most of the Refugees in Izmir Live Here? | Walking Tour Turkey 4K 60fps","description":"If you''re interested in experiencing Izmir in a different way, then this is the perfect tour for you! During this walk, you will see the city from a unique perspective. You will also have an idea about the living spaces of refugees. Basmane area has been hosting refugees for centuries. After our walk in Basmane, we will pass through the streets of the historical Kemeraltı bazaar and go to Çankaya area. İzmir walking Tour Konak district March 7, 2023 3 pm Tuesday Temperature: +16 ℃ Contact: izmirexplorer@gmail.com #izmir #turkey #walk #walkingtour","thumbnail":"https://i.ytimg.com/vi/_x0d_50wiUg/maxresdefault.jpg","category":"Walking Tours","city":"Izmir","country":"Turkey","channel":"Still Walking","channelTitle":"Still Walking","channelId":"UCD9clPtpOTsz7PPrm2JpafQ","badge":"4K 60FPS","publishedAt":"2023-03-09T14:00:37Z","viewCount