INSERT OR IGNORE INTO videos (id,title,description,thumbnail,category,channel,channel_title,channel_id,badge,published_at,city,country,raw_json,active) VALUES ('QpC2Ls3ZQsQ','A Summer Night Walk in İzmir Alsancak (Turkey 2023) 4K Walking Tour','It''s a summer night in Alsancak, İzmir. The time is 11pm. We start our walk on Bornova Street, a transit street. I love walking on this street. Then we walk on Cyprus Martyrs Street, a wider street, and slowly move away from the area towards the Lozan Square. This is the city center and there is not much crowd due to the summer season. Because İzmir has numerous holiday resorts and most people are on vacation according to their budget. I hope you enjoy our walking tour! Please don''t forget to subscribe to my channel. İzmir walking tour Konak district Alsancak neighborhood July 17, 2023 11 pm monday Temperature: +36 ℃ Contact: izmirexplorer@gmail.com #izmir #turkey #walkingtour İzmir Alsancak''ta Bir Yaz Gecesi Yürüyüşü (Temmuz 2023) 4K Video','https://i.ytimg.com/vi/QpC2Ls3ZQsQ/maxresdefault.jpg','Night & Rain','Still Walking','Still Walking','UCD9clPtpOTsz7PPrm2JpafQ','4K 60FPS','2023-07-18T17:00:16Z','Izmir','Turkey','{"id":"QpC2Ls3ZQsQ","title":"A Summer Night Walk in İzmir Alsancak (Turkey 2023) 4K Walking Tour","description":"It''s a summer night in Alsancak, İzmir. The time is 11pm. We start our walk on Bornova Street, a transit street. I love walking on this street. Then we walk on Cyprus Martyrs Street, a wider street, and slowly move away from the area towards the Lozan Square. This is the city center and there is not much crowd due to the summer season. Because İzmir has numerous holiday resorts and most people are on vacation according to their budget. I hope you enjoy our walking tour! Please don''t forget to subscribe to my channel. İzmir walking tour Konak district Alsancak neighborhood July 17, 2023 11 pm monday Temperature: +36 ℃ Contact: izmirexplorer@gmail.com #izmir #turkey #walkingtour İzmir Alsancak''ta Bir Yaz Gecesi Yürüyüşü (Temmuz 2023) 4K Video","thumbnail":"https://i.ytimg.com/vi/QpC2Ls3ZQsQ/maxresdefault.jpg","category":"Night & Rain","city":"Izmir","country":"Turkey","channel":"Still Walking","channelTitle":"Still Walking","channelId":"UCD9clPtpOTsz7PPrm2JpafQ","badge":"4K 60FPS","publishedAt":"2023-07-18T17:00:16Z","viewCount":13024,"durationSeconds":2070,"admission":{"version":3,"status":"channel-candidate","source":"channel-archive","mode":"CITY"}}','1');
