INSERT OR IGNORE INTO videos (id,title,description,thumbnail,category,channel,channel_title,channel_id,badge,published_at,city,country,raw_json,active) VALUES ('7XDRZNrv1-4','Izmir, Turkey: Walk Like a Göztepe Fan in Izmir | Izmir Walking Tour 2023 (4K 60fps)','Happy 98th birthday, Göztepe Club! Göztepe fans are coming together on June 14th, as they do every year, to celebrate the club''s birthday. We''ll be taking a walking tour of Göztepe neighborhood to share in the enthusiasm. If you''re in Izmir in June, don''t make any plans for the 14th. Put on your Göztepe jersey and come join us for a real local experience. İzmir walking tour Konak district Güzelyalı neighborhood June 14, 2023 8.30 pm wednesday Temperature: +31 ℃ Contact: izmirexplorer@gmail.com #izmir #turkey #walkingtour Göztepe Tutkusu: Sınır Tanımayan Kulüp Aşkı | 4K İzmir Turu - 14 Haziran 2023','https://i.ytimg.com/vi/7XDRZNrv1-4/maxresdefault.jpg','Walking Tours','Still Walking','Still Walking','UCD9clPtpOTsz7PPrm2JpafQ','4K 60FPS','2023-06-16T16:00:04Z','Izmir','Turkey','{"id":"7XDRZNrv1-4","title":"Izmir, Turkey: Walk Like a Göztepe Fan in Izmir | Izmir Walking Tour 2023 (4K 60fps)","description":"Happy 98th birthday, Göztepe Club! Göztepe fans are coming together on June 14th, as they do every year, to celebrate the club''s birthday. We''ll be taking a walking tour of Göztepe neighborhood to share in the enthusiasm. If you''re in Izmir in June, don''t make any plans for the 14th. Put on your Göztepe jersey and come join us for a real local experience. İzmir walking tour Konak district Güzelyalı neighborhood June 14, 2023 8.30 pm wednesday Temperature: +31 ℃ Contact: izmirexplorer@gmail.com #izmir #turkey #walkingtour Göztepe Tutkusu: Sınır Tanımayan Kulüp Aşkı | 4K İzmir Turu - 14 Haziran 2023","thumbnail":"https://i.ytimg.com/vi/7XDRZNrv1-4/maxresdefault.jpg","category":"Walking Tours","city":"Izmir","country":"Turkey","channel":"Still Walking","channelTitle":"Still Walking","channelId":"UCD9clPt