INSERT OR IGNORE INTO videos (id,title,description,thumbnail,category,channel,channel_title,channel_id,badge,published_at,city,country,raw_json,active) VALUES ('3n8fbJD66oE','🇹🇷 A Walk Through İzmir: Discovering the City''s Contrasts - 76 Min 🚶‍♂️','Our walk starts in İkiçeşmelik. It''s a rather dilapidated area, but it''s the heart of the city''s second-hand goods and white goods trade. Next, we''ll visit Basmane, the city''s ghetto, which has been home to refugees for centuries. Then we''ll pass through the Çankaya district and head to Alsancak, one of the most beautiful neighborhoods in the city. The contrast between the different areas is truly striking. Enjoy the walk! 🇹🇷 A Walk Through İzmir: Discovering the City''s Contrasts - 76 Min 🚶‍♂️ 00:00 İkiçeşmelik 12:14 Basmane 30:20 Çankaya 52:20 Alsancak İzmir walking tour Konak district March 4, 2024 4pm Monday Temperature: +18 ℃ Contact: izmirexplorer@gmail.com #izmir #turkey #walkingtour #citylife #streettour İzmir''de Bir Yürüyüş: Zıtlıklarla Dolu Bir Şehir (İkiçeşmelik, Basmane, Alsancak)','https://i.ytimg.com/vi/3n8fbJD66oE/maxresdefault.jpg','Walking Tours','Still Walking','Still Walking','UCD9clPtpOTsz7PPrm2JpafQ','4K 60FPS','2024-03-05T15:45:00Z','Izmir','Turkey','{"id":"3n8fbJD66oE","title":"🇹🇷 A Walk Through İzmir: Discovering the City''s Contrasts - 76 Min 🚶‍♂️","description":"Our walk starts in İkiçeşmelik. It''s a rather dilapidated area, but it''s the heart of the city''s second-hand goods and white goods trade. Next, we''ll visit Basmane, the city''s ghetto, which has been home to refugees for centuries. Then we''ll pass through the Çankaya district and head to Alsancak, one of the most beautiful neighborhoods in the city. The contrast between the different areas is truly striking. Enjoy the walk! 🇹🇷 A Walk Through İzmir: Discovering the City''s Contrasts - 76 Min 🚶‍♂️ 00:00 İkiçeşmelik 12:14 Basmane 30:20 Çankaya 52:20 Alsancak İzmir walking tour Konak district March 4, 2024 4pm Monday Temperature: