INSERT OR IGNORE INTO videos (id,title,description,thumbnail,category,channel,channel_title,channel_id,badge,published_at,city,country,raw_json,active) VALUES ('iciI1yY_zBc','One of İzmir''s Best Evenings — And Most Tourists Never See It | Bostanlı 4K Walk (Türkiye)','Izmir evening walk in Bostanlı: Welcome to one of İzmir''s most vibrant local neighborhoods after sunset. While many visitors head to Alsancak, Çeşme, or Alaçatı, Bostanlı offers a completely different side of İzmir — lively streets, packed cafés, restaurants full of conversation, and the everyday social life of local residents. In this 4K walking tour, we explore the atmosphere of a warm summer evening as the neighborhood comes alive. From busy streets and outdoor dining to unexpected moments of daily life, this walk captures a side of İzmir that many tourists never get to experience. 📍 Bostanlı, Karşıyaka, İzmir, Türkiye 🌡️ Weather: 31°C 🕘 Time: 8:30 PM 📅 Date: June 6, 2026 🎥 4K 60fps Walking Tour still walking 👣 continue walking here: 👉https://www.youtube.com/playlist?list=PLe0tLqhfoJ0lD4ABpCnNmKAxMpHq607gz from an earlier time: 👉 https://www.youtube.com/playlist?list=PLe0tLqhfoJ0kA5DZ-hMOT5mX-rHSVN8EK Contact: izmirexplorer@gmail.com #izmir #bostanlı #eveningwalk #turkeytravel #citywalk #stillwalking #walkingtour','https://i.ytimg.com/vi/iciI1yY_zBc/maxresdefault.jpg','Walking Tours','Still Walking','Still Walking','UCD9clPtpOTsz7PPrm2JpafQ','4K 60FPS','2026-06-07T11:45:18Z','Izmir','Turkey','{"id":"iciI1yY_zBc","title":"One of İzmir''s Best Evenings — And Most Tourists Never See It | Bostanlı 4K Walk (Türkiye)","description":"Izmir evening walk in Bostanlı: Welcome to one of İzmir''s most vibrant local neighborhoods after sunset. While many visitors head to Alsancak, Çeşme, or Alaçatı, Bostanlı offers a completely different side of İzmir — lively streets, packed cafés, restaurants full of conversation, and the everyday social life of local residents. In this 4K walking tour, we explore the atmosphere of a warm summer evening as the neighborhood comes alive. From busy streets and outdoor dining to unexpected moments of daily life, this walk captures a side of İzmir that many tourists never get to experience. 📍 Bostanlı, Karşıyaka, İzmir, Türkiye 🌡️ Weather: 31°C 🕘 Time: 8:30 PM 📅 Date: June 6, 2026 🎥 4K 60fps Walking Tour still walking 👣 continue walking here: 👉https://www.youtube.com/playlist?list=PLe0tLqhfoJ0lD4ABpCnNmKAxMpHq607gz from an earlier time: 👉 https://www.youtube.com/playlist?list=PLe0tLqhfoJ0kA5DZ-hMOT5mX-rHSVN8EK Contact: izmirexplorer@gmail.com #izmir #bostanlı #eveningwalk #turkeytravel #citywalk #stillwalking #walkingtour","thumbnail":"https://i.ytimg.com/vi/iciI1yY_zBc/maxresdefault.jpg","category":"Walking Tours","city":"Izmir","country":"Turkey","channel":"Still Walking","channelTitle":"Still Walking","channelId":"UCD9clPtpOTsz7PPrm2JpafQ","badge":"4K 60FPS","publishedAt":"2026-06-07T11:45:18Z","viewCount":7906,"durationSeconds":1811,"admission":{"version":3,"status":"channel-candidate","source":"channel-archive","mode":"CITY"}}','1');
