INSERT OR IGNORE INTO videos (id,title,description,thumbnail,category,channel,channel_title,channel_id,badge,published_at,city,country,raw_json,active) VALUES ('p3VRImZUHC4','The Contrast of Izmir: From Silent Alleys to Crowded Kemeraltı (4K Walk) — still walking 🇹🇷','The Contrast of Izmir: From Silent Alleys to Crowded Kemeraltı (4K Walk) — still walking 🇹🇷 This İzmir walking tour begins with the iconic, panoramic views of Varyant, where the journey slowly drifts into the city''s deepest layers. This 4K walk is a study of urban contrast: moving from silent, hidden backstreets and steep stairways to the vibrant, pulsing energy of Kemeraltı. Along the way, the path reveals abandoned buildings, unexpected encounters, and historical details that many pass without noticing. In these İzmir backstreets, there was a point where the direction no longer mattered — and that’s where the real discovery of the historic bazaar began. From the stillness of the heights to the crowded alleys of the old town, this is not just a route. This is a feeling of a city that never stops breathing. Captured with natural ambient sounds and long uninterrupted sequences to bring you the authentic rhythm of Kemeraltı and beyond. still walking 👣 📍 Konak, Kemeraltı Bazaar, Izmir — Türkiye ⏱ Real time – No talking – Natural sound continue walking here: 👉https://www.youtube.com/playlist?list=PLe0tLqhfoJ0lD4ABpCnNmKAxMpHq607gz from an earlier time: 👉 https://www.youtube.com/playlist?list=PLe0tLqhfoJ0kA5DZ-hMOT5mX-rHSVN8EK Contact: izmirexplorer@gmail.com #StillWalking #Izmir #WalkingTour #CityWalk #OldTown #turkey #kemeraltı','https://i.ytimg.com/vi/p3VRImZUHC4/maxresdefault.jpg','Walking Tours','Still Walking','Still Walking','UCD9clPtpOTsz7PPrm2JpafQ','4K 60FPS','2026-02-21T08:30:04Z','Izmir','Turkey','{"id":"p3VRImZUHC4","title":"The Contrast of Izmir: From Silent Alleys to Crowded Kemeraltı (4K Walk) — still walking 🇹🇷","description":"The Contrast of Izmir: From Silent Alleys to Crowded Kemeraltı 