INSERT OR IGNORE INTO videos (id,title,description,thumbnail,category,channel,channel_title,channel_id,badge,published_at,city,country,raw_json,active) VALUES ('55Xe-Lvay60','Explore İzmir Buca''s Identity: 4K Virtual Walking Tour | Turkey Travel','Through this walking tour, we aim to explore the essence of İzmir Buca. Initially, as we wander through the backstreets, we are astonished by the abundance of contemporary cafes, each capturing unique concepts. Afterwards, passing by the forest-like Hasanağa Park, we proceed towards the historical heart of Buca. Upon reaching our destination, we''re greeted by preserved magnificent structures, derelict buildings, and unique streets. We hope you enjoy the journey through Buca. Have a great day, everyone! İzmir walking tour Buca district November 27, 2023 3 pm monday Temperature: +13 ℃ Explore İzmir Buca''s Identity: 4K Virtual Walking Tour | Turkey Travel Contact: izmirexplorer@gmail.com #izmir #turkey #walkingtour #buca #citylife #streettour İzmir Buca''yı Keşfedin: 4K Sanal Yürüyüş Turu | Buca Sokakları','https://i.ytimg.com/vi/55Xe-Lvay60/maxresdefault.jpg','Walking Tours','Still Walking','Still Walking','UCD9clPtpOTsz7PPrm2JpafQ','4K 60FPS','2023-11-28T13:45:00Z','Izmir','Turkey','{"id":"55Xe-Lvay60","title":"Explore İzmir Buca''s Identity: 4K Virtual Walking Tour | Turkey Travel","description":"Through this walking tour, we aim to explore the essence of İzmir Buca. Initially, as we wander through the backstreets, we are astonished by the abundance of contemporary cafes, each capturing unique concepts. Afterwards, passing by the forest-like Hasanağa Park, we proceed towards the historical heart of Buca. Upon reaching our destination, we''re greeted by preserved magnificent structures, derelict buildings, and unique streets. We hope you enjoy the journey through Buca. Have a great day, everyone! İzmir walking tour Buca district November 27, 2023 3 pm monday Temperature: +13 ℃ Explore İzmir Buca''s Identity: 4K Virtual W