INSERT OR IGNORE INTO videos (id,title,description,thumbnail,category,channel,channel_title,channel_id,badge,published_at,city,country,raw_json,active) VALUES ('a62MsNlTaPs','A Walking Tour of Bostanlı, Izmir''s Charming Coastal Neighborhood | Izmir City Walk 2023','A Walking Tour of Bostanlı, İzmir''s Charming Coastal Neighborhood Hi everyone! Join me on an evening stroll through Bostanlı, the charming coastal neighborhood of İzmir. We''ll start our walk at the coastal promenade at twilight, where you can feel the peace of the evening wash over you. Then, we''ll wander through the neighborhood and take in all that Bostanlı has to offer, from its wonderful cafes and bars to its vibrant streets. Bostanlı is a neighborhood in the district of Karşıyaka, and I hope you enjoy the walk as much as I do! İzmir walking tour Karşıyaka district Bostanlı neighborhood June 15, 2023 9 pm thursday Temperature: +31 ℃ 00:00 Preview 01:16 Coastal promenade 17:23 Cemal Bülbül St. 20:10 Cemal Gürsel St. 24:34 Cengiz Topel St. Contact: izmirexplorer@gmail.com #izmir #turkey #walkingtour İzmir Bostanlı''da Bir Gezinti: Huzurlu Bir Akşam Kaçamağı | 4K İzmir Turu','https://i.ytimg.com/vi/a62MsNlTaPs/maxresdefault.jpg','Beach Walking Tours','Still Walking','Still Walking','UCD9clPtpOTsz7PPrm2JpafQ','4K 60FPS','2023-06-17T16:00:00Z','Izmir','Turkey','{"id":"a62MsNlTaPs","title":"A Walking Tour of Bostanlı, Izmir''s Charming Coastal Neighborhood | Izmir City Walk 2023","description":"A Walking Tour of Bostanlı, İzmir''s Charming Coastal Neighborhood Hi everyone! Join me on an evening stroll through Bostanlı, the charming coastal neighborhood of İzmir. We''ll start our walk at the coastal promenade at twilight, where you can feel the peace of the evening wash over you. Then, we''ll wander through the neighborhood and take in all that Bostanlı has to offer, from its wonderful cafes and bars to its vibrant streets. Bostanlı is a neighborhood in the district of Karşıyaka, and I hope you enjoy the walk as much as I do! İzmir walking tour Karşıyaka district Bostanlı neighborhood June 15, 2023 9 pm thursday Temperature: +31 ℃ 00:00 Preview 01:16 Coastal promenade 17:23 Cemal Bülbül St. 20:10 Cemal Gürsel St. 24:34 Cengiz Topel St. Contact: izmirexplorer@gmail.com #izmir #turkey #walkingtour İzmir Bostanlı''da Bir Gezinti: Huzurlu Bir Akşam Kaçamağı | 4K İzmir Turu","thumbnail":"https://i.ytimg.com/vi/a62MsNlTaPs/maxresdefault.jpg","category":"Beach Walking Tours","city":"Izmir","country":"Turkey","channel":"Still Walking","channelTitle":"Still Walking","channelId":"UCD9clPtpOTsz7PPrm2JpafQ","badge":"4K 60FPS","publishedAt":"2023-06-17T16:00:00Z","viewCount":6788,"durationSeconds":1920,"admission":{"version":3,"status":"channel-candidate","source":"channel-archive","mode":"CITY"}}','1');
