INSERT OR IGNORE INTO videos (id,title,description,thumbnail,category,channel,channel_title,channel_id,badge,published_at,city,country,raw_json,active) VALUES ('nJwdxzeluag','[4K] Izmir Walking Tour | From ALSANCAK to Hilal Metro Station, 24 August 2021 | 🇹🇷 Turkey','Walking tour from Alsancak Cumhuriyet Boulevard to Hilal Metro station. Hilal metro station is in a very interesting place. The other side of the station is the Çukur (pit) neighborhood. a real ghetto. The city''s drug traffic also revolves around this neighborhood. Timeline: 0:00 Cumhuriyet Blv. 3:25 Dr. Mustafa Enver Bey Street 5:15 Meksika st. 6:30 1382 st. (Gül sokak) 8:20 Plevne Blv. 10:10 Lozan square 10:40 Şair Eşref Blv. 14:30 Ali Çetinkaya Blv. 20:20 1420 st. 22:25 Mimar Sinan Street 23:00 Nevzat Güzelırmak st. (Kahramanlar) 25:40 Hilal Metro Station Alsancak walking tour 6.30pm Tuesday August 24, 2021 Temperature: +35 ℃ [4K] Izmir Walking Tour | From ALSANCAK to Hilal Metro Station, 24 August 2021 | 🇹🇷 Turkey #izmirexplorer #izmir #alsancak #turkey #streetwalk #summer2021 #turkeyvlog #türkei #izmirvlog #cityambiance #turkey2021 #walk #turkeytravel #travel #virtualwalk #virtualtour #virtualtravel #august2021 #izmir2021 #izmircity #izmirwalk #4kvideo #citywalks #türkiye #walkingtour #esmirna #Измир','https://i.ytimg.com/vi/nJwdxzeluag/maxresdefault.jpg','Walking Tours','Still Walking','Still Walking','UCD9clPtpOTsz7PPrm2JpafQ','4K 60FPS','2021-08-25T16:00:21Z','Izmir','Turkey','{"id":"nJwdxzeluag","title":"[4K] Izmir Walking Tour | From ALSANCAK to Hilal Metro Station, 24 August 2021 | 🇹🇷 Turkey","description":"Walking tour from Alsancak Cumhuriyet Boulevard to Hilal Metro station. Hilal metro station is in a very interesting place. The other side of the station is the Çukur (pit) neighborhood. a real ghetto. The city''s drug traffic also revolves around this neighborhood. Timeline: 0:00 Cumhuriyet Blv. 3:25 Dr. Mustafa Enver Bey Street 5:15 Meksika st. 6:30 1382 st. (Gül sokak) 8:20 Plevne Blv. 10:10 Lozan square 10:40 Şair Eşref Blv. 14:30 Ali Çetinkaya Blv. 20:20 1420 st. 22:25 Mimar Sinan Street 23:00 Nevzat Güzelırmak st. (Kahramanlar) 25:40 Hilal Metro Station Alsancak walking tour 6.30pm Tuesday August 24, 2021 Temperature: +35 ℃ [4K] Izmir Walking Tour | From ALSANCAK to Hilal Metro Station, 24 August 2021 | 🇹🇷 Turkey #izmirexplorer #izmir #alsancak #turkey #streetwalk #summer2021 #turkeyvlog #türkei #izmirvlog #cityambiance #turkey2021 #walk #turkeytravel #travel #virtualwalk #virtualtour #virtualtravel #august2021 #izmir2021 #izmircity #izmirwalk #4kvideo #citywalks #türkiye #walkingtour #esmirna #Измир","thumbnail":"https://i.ytimg.com/vi/nJwdxzeluag/maxresdefault.jpg","category":"Walking Tours","city":"Izmir","country":"Turkey","channel":"Still Walking","channelTitle":"Still Walking","channelId":"UCD9clPtpOTsz7PPrm2JpafQ","badge":"4K 60FPS","publishedAt":"2021-08-25T16:00:21Z","viewCount":5780,"durationSeconds":1926,"admission":{"version":3,"status":"channel-candidate","source":"channel-archive","mode":"CITY"}}','1');
