INSERT OR IGNORE INTO videos (id,title,description,thumbnail,category,channel,channel_title,channel_id,badge,published_at,city,country,raw_json,active) VALUES ('_LKOhfqLqBs','Rainy Day in Izmir’s Alsancak – From Crowded Streets to Mysterious Backstreets | 4K Walk 🇹🇷','Take a rainy walk through Izmir’s vibrant Alsancak neighborhood! In this 4K walking tour, we move from the lively, crowded streets of Alsancak to its peaceful backstreets — exploring the contrast between the buzzing city life and the quiet charm hidden in the neighborhood’s heart. This video captures the real atmosphere of Izmir on a rainy day: reflections on the wet pavement, street sounds, local life, and unexpected cozy corners. Whether you’ve been to Turkey or are just dreaming of visiting, this walk offers a unique glimpse into everyday life in one of Izmir’s most iconic districts. 📍 Location: Alsancak, Izmir, Turkey 🎥 Shot in: 4K UHD 🌧️ Weather: Rainy 🎶 Natural ambient sounds (no music, no talking) Izmir Walking Tour 🚶‍♂️ Konak District 🏛️ Date: April 12, 2025 (Saturday) 📅 Time: 5:00 PM 🕓 Temperature: 14°C 🌡️ Rainy Day in Izmir’s Alsancak – From Crowded Streets to Mysterious Backstreets | 4K Walk 🇹🇷 All Izmir walking tours here: Real Izmir Walking Tours 4K 🇹🇷 https://www.youtube.com/playlist?list=PLe0tLqhfoJ0kA5DZ-hMOT5mX-rHSVN8EK Contact: izmirexplorer@gmail.com #İzmir #turkey #alsancak #streetwalk #walkingtour #izmirtour #rainyday #RainyWalk #TurkeyWalk #4KWalk #CityWalk #RainyDayVibes #UrbanExploration #IzmirStreets #AlsancakWalk #BackstreetsOfIzmir #WalkingInTheRain #VirtualTravel','https://i.ytimg.com/vi/_LKOhfqLqBs/maxresdefault.jpg','Night & Rain','Still Walking','Still Walking','UCD9clPtpOTsz7PPrm2JpafQ','RAIN 4K','2025-04-13T11:00:49Z','Izmir','Turkey','{"id":"_LKOhfqLqBs","title":"Rainy Day in Izmir’s Alsancak – From Crowded Streets to Mysterious Backstreets | 4K Walk 🇹🇷","description":"Take a rainy walk through Izmir’s vibrant Alsancak neighborhood! In this 4K walking tour, we move from the lively, crowded streets of Alsancak to its peaceful backstreets — exploring the contrast between the buzzing city life and the quiet charm hidden in the neighborhood’s heart. This video captures the real atmosphere of Izmir on a rainy day: reflections on the wet pavement, street sounds, local life, and unexpected cozy corners. Whether you’ve been to Turkey or are just dreaming of visiting, this walk offers a unique glimpse into everyday life in one of Izmir’s most iconic districts. 📍 Location: Alsancak, Izmir, Turkey 🎥 Shot in: 4K UHD 🌧️ Weather: Rainy 🎶 Natural ambient sounds (no music, no talking) Izmir Walking Tour 🚶‍♂️ Konak District 🏛️ Date: April 12, 2025 (Saturday) 📅 Time: 5:00 PM 🕓 Temperature: 14°C 🌡️ Rainy Day in Izmir’s Alsancak – From Crowded Streets to Mysterious Backstreets | 4K Walk 🇹🇷 All Izmir walking tours here: Real Izmir Walking Tours 4K 🇹🇷 https://www.youtube.com/playlist?list=PLe0tLqhfoJ0kA5DZ-hMOT5mX-rHSVN8EK Contact: izmirexplorer@gmail.com #İzmir #turkey #alsancak #streetwalk #walkingtour #izmirtour #rainyday #RainyWalk #TurkeyWalk #4KWalk #CityWalk #RainyDayVibes #UrbanExploration #IzmirStreets #AlsancakWalk #BackstreetsOfIzmir #WalkingInTheRain #VirtualTravel","thumbnail":"https://i.ytimg.com/vi/_LKOhfqLqBs/maxresdefault.jpg","category":"Night & Rain","city":"Izmir","country":"Turkey","channel":"Still Walking","channelTitle":"Still Walking","channelId":"UCD9clPtpOTsz7PPrm2JpafQ","badge":"RAIN 4K","publishedAt":"2025-04-13T11:00:49Z","viewCount":4618,"durationSeconds":4162,"admission":{"version":3,"status":"channel-candidate","source":"channel-archive","mode":"CITY"}}','1');
