INSERT OR IGNORE INTO videos (id,title,description,thumbnail,category,channel,channel_title,channel_id,badge,published_at,city,country,raw_json,active) VALUES ('1m1_YNoqKcM','4K İzmir Walking Tour on İzmir''s Independence Day (Sep 9, 2023) Turkey','Discover the heart of İzmir like never before in this captivating 1-hour walking tour along the city''s stunning waterfront, just before the Independence Day celebrations. Join the bustling crowd as you stroll from Konak to Alsancak port, immersing yourself in the picturesque views of İzmir''s coastal beauty. But that''s not all – keep your eyes peeled for an unexpected surprise as horsemen gallop onto the scene, injecting an exhilarating sense of adventure into your waterfront journey. Get ready for a remarkable experience that will leave you enchanted by İzmir''s vibrant spirit! İzmir walking tour Konak district September 9, 2023 5 pm saturday Temperature: +32 ℃ Contact: izmirexplorer@gmail.com #izmir #turkey #walkingtour','https://i.ytimg.com/vi/1m1_YNoqKcM/maxresdefault.jpg','Walking Tours','Still Walking','Still Walking','UCD9clPtpOTsz7PPrm2JpafQ','4K 60FPS','2023-09-10T12:10:11Z','Izmir','Turkey','{"id":"1m1_YNoqKcM","title":"4K İzmir Walking Tour on İzmir''s Independence Day (Sep 9, 2023) Turkey","description":"Discover the heart of İzmir like never before in this captivating 1-hour walking tour along the city''s stunning waterfront, just before the Independence Day celebrations. Join the bustling crowd as you stroll from Konak to Alsancak port, immersing yourself in the picturesque views of İzmir''s coastal beauty. But that''s not all – keep your eyes peeled for an unexpected surprise as horsemen gallop onto the scene, injecting an exhilarating sense of adventure into your waterfront journey. Get ready for a remarkable experience that will leave you enchanted by İzmir''s vibrant spirit! İzmir walking tour Konak district September 9, 2023 5 pm saturday Temperature: +32 ℃ Contact: izmirexplorer@gmail.com #izmir #turkey #walkingtour","thumbnail":"https://i.ytimg.com/vi/1m1_YNoqKcM/maxresdefault.jpg","category":"Walking Tours","city":"Izmir","country":"Turkey","channel":"Still Walking","channelTitle":"Still Walking","channelId":"UCD9clPtpOTsz7PPrm2JpafQ","badge":"4K 60FPS","publishedAt":"2023-09-10T12:10:11Z","viewCount":4577,"durationSeconds":3754,"admission":{"version":3,"status":"channel-candidate","source":"channel-archive","mode":"CITY"}}','1');
INSERT OR IGNORE INTO videos (id,title,description,thumbnail,category,channel,channel_title,channel_id,badge,published_at,city,country,raw_json,active) VALUES ('O9ccug6rzEM','4K İzmir: A Walking Tour in Güzelyalı Neighborhood - New Video!','Taking a walking tour in Güzelyalı neighborhood, located within the Konak district: We start our walk along the seaside, accompanied by a captivating view, then proceed into the heart of the neighborhood by crossing the bridge. After exploring the streets of Güzelyalı and the cafes and pubs along the promenade, we conclude the video at the Notre Dame de Lourdes Catholic Church. I hope you enjoy the video! Have a great day! İzmir walking tour Konak district Güzelyalı neighborhood November 25, 2023 5 pm saturday Temperature: +19 ℃ 4K İzmir: A Walking Tour in Güzelyalı Neighborhood - New Video! Contact: izmirexplorer@gmail.com #izmir #turkey #walkingtour #konak #güzelyalı #citylife #streettour','https://i.ytimg.com/vi/O9ccug6rzEM/maxresdefault.jpg','Walking Tours','Still Walking','Still Walking','UCD9clPtpOTsz7PPrm2JpafQ','4K 60FPS','2023-11-26T09:45:11Z','Izmir','Turkey','{"id":"O9ccug6rzEM","title":"4K İzmir: A Walking Tour in Güzelyalı Neighborhood - New Video!","description":"Taking a walking tour in Güzelyalı neighborhood, located within the Konak district: We start our walk along the seaside, accompanied by a captivating view, then proceed into the heart of the neighborhood by crossing the bridge. After exploring the streets of Güzelyalı and the cafes and pubs along the promenade, we conclude the video at the Notre Dame de Lourdes Catholic Church. I hope you enjoy the video! Have a great day! İzmir walking tour Konak district Güzelyalı neighborhood November 25, 2023 5 pm saturday Temperature: +19 ℃ 4K İzmir: A Walking Tour in Güzelyalı Neighborhood - New Video! Contact: izmirexplorer@gmail.com #izmir #turkey #walkingtour #konak #güzelyalı #citylife #streettour","thumbnail":"https://i.ytimg.com/vi/O9ccug6rzEM/maxresdefault.jpg"