INSERT OR IGNORE INTO videos (id,title,description,thumbnail,category,channel,channel_title,channel_id,badge,published_at,city,country,raw_json,active) VALUES ('VOI2V46VJoc','🇹🇷 İzmir Exploration: Walk in the Narrow and Challenging Yeşilyurt Neighborhood','Exploring Yeşilyurt Neighborhood, one of the high-altitude districts in Izmir compared to the city center. The streets and sidewalks are narrow. Traffic is two-way, making walking quite challenging. After taking a tour around the neighborhood, we descend to Hatay Neighborhood below and witness the contrast. Enjoy your walks! İzmir walking tour Karabağlar district March 6, 2024 4pm Wednesday Temperature: +18 ℃ 🇹🇷 İzmir Exploration: Walk in the Narrow and Challenging Yeşilyurt Neighborhood Contact: izmirexplorer@gmail.com #izmir #turkey #walkingtour #citylife #streettour İzmir Yeşilyurt Sokakları: Hatay Semtine Uzanan Bir Yürüyüş - 54 Dakika 🚶‍♂️','https://i.ytimg.com/vi/VOI2V46VJoc/maxresdefault.jpg','Walking Tours','Still Walking','Still Walking','UCD9clPtpOTsz7PPrm2JpafQ','4K 60FPS','2024-03-07T15:45:02Z','Izmir','Turkey','{"id":"VOI2V46VJoc","title":"🇹🇷 İzmir Exploration: Walk in the Narrow and Challenging Yeşilyurt Neighborhood","description":"Exploring Yeşilyurt Neighborhood, one of the high-altitude districts in Izmir compared to the city center. The streets and sidewalks are narrow. Traffic is two-way, making walking quite challenging. After taking a tour around the neighborhood, we descend to Hatay Neighborhood below and witness the contrast. Enjoy your walks! İzmir walking tour Karabağlar district March 6, 2024 4pm Wednesday Temperature: +18 ℃ 🇹🇷 İzmir Exploration: Walk in the Narrow and Challenging Yeşilyurt Neighborhood Contact: izmirexplorer@gmail.com #izmir #turkey #walkingtour #citylife #streettour İzmir Yeşilyurt Sokakları: Hatay Semtine Uzanan Bir Yürüyüş - 54 Dakika 🚶‍♂️","thumbnail":"https://i.ytimg.com/vi/VOI2V46VJoc/maxresdefault.jpg","category":"Walking Tours","city":"Izmir","country":"Turkey",