INSERT OR IGNORE INTO videos (id,title,description,thumbnail,category,channel,channel_title,channel_id,badge,published_at,city,country,raw_json,active) VALUES ('zwmdTLHLPT8','Izmir Street Walk 🇹🇷 A Different Route Every Time | Izmir Walking Tour 2023 | Hatay to Karataş','Izmir street walk 🇹🇷 a different route every time: In this video, we''ll take you on a walking tour from Hatay to Karataş. First, we''ll stroll slowly towards Üçyol, taking in the sights of the busy Hatay Street shops. We''ll also explore the back streets and parks so you can experience Izmir like a local. After reaching Üçyol, we''ll descend from 140 meters above sea level to Karataş. We''ll finish our walking tour on the Karataş coast after descending the slopes and steep streets. İzmir walking tour May 25, 2023 4 pm Thursday Temperature: +23 ℃ Contact: izmirexplorer@gmail.com #izmir #turkey #walkingtour 4K İzmir Turu | Şehri Görmenin Mükemmel Yolu | İzmir Hatay - Üçyol - Karataş','https://i.ytimg.com/vi/zwmdTLHLPT8/maxresdefault.jpg','Walking Tours','Still Walking','Still Walking','UCD9clPtpOTsz7PPrm2JpafQ','4K 60FPS','2023-05-26T15:45:07Z','Izmir','Turkey','{"id":"zwmdTLHLPT8","title":"Izmir Street Walk 🇹🇷 A Different Route Every Time | Izmir Walking Tour 2023 | Hatay to Karataş","description":"Izmir street walk 🇹🇷 a different route every time: In this video, we''ll take you on a walking tour from Hatay to Karataş. First, we''ll stroll slowly towards Üçyol, taking in the sights of the busy Hatay Street shops. We''ll also explore the back streets and parks so you can experience Izmir like a local. After reaching Üçyol, we''ll descend from 140 meters above sea level to Karataş. We''ll finish our walking tour on the Karataş coast after descending the slopes and steep streets. İzmir walking tour May 25, 2023 4 pm Thursday Temperature: +23 ℃ Contact: izmirexplorer@gmail.com #izmir #turkey #walkingtour 4K İzmir Turu | Şehri Görmenin Mükemmel Yolu | İzmir Hatay - Üçyol - Karataş","thumbnail":"https://i