INSERT OR IGNORE INTO videos (id,title,description,thumbnail,category,channel,channel_title,channel_id,badge,published_at,city,country,raw_json,active) VALUES ('qcuH8m1uMOo','Don''t Miss This Sunset in Izmir: Cozy Walk From Coast to Alsancak Backstreets 🌅 | Turkey 4K','Experience the magical transition of Izmir from a golden sunset to the vibrant, hidden nightlife of Alsancak in full 4K 60fps. The journey begins on the iconic Kordon coastline during the golden hour. Everyone is in a total chill mood—some are freezing the moment with their cameras, some are taking a peaceful evening walk, while others are relaxing on the grass, enjoying the sunset vibe from every angle. After capturing the beautiful seaside ambience and the lively beachfront restaurants, we head deep into the heart of the city. As you walk through the streets, you will instantly feel Izmir’s genetic holiday vibe. Soon, we arrive at the most famous and crowded avenue of the city: Kibris Sehitleri Avenue. The energy here is unmatched! From this bustling main street, we dive into the fascinating maze of Alsancak''s side streets (alleys). Moving left and right through these passages, we discover the real soul of the city: taverns, hidden cafe-bars, lively crowds, and sudden pockets of serene silence. Finally, the walk concludes with a magnificent urban contrast—the historic Alsancak Train Station standing proud against the newly built, illuminated modern residences, perfectly captured just as the city tram passes by. No talking, no narration—just pure real-time walking and natural ambient city sounds. still walking 👣 📍 Location: Alsancak, İzmir, Turkey 📅 Date: May 28, 2026 (Thursday) 🕓 Time: 8:00 PM 🌡️ Temperature: 21°C continue walking here: 👉https://www.youtube.com/playlist?list=PLe0tLqhfoJ0lD4ABpCnNmKAxMpHq607gz from an earlier time: 👉 https://www.youtube.com/playlist?list=PLe0tLqhfoJ0kA5DZ-hMOT5mX-rHSVN8EK Contact: izmirexplorer@gmail.com #izmir #alsancak #walkingtour #sunsetwalk #turkeytravel #eveningwalk','https://i.ytimg.com/vi/qcuH8m1uMOo/maxresdefault.jpg','Walking Tours','Still Walking','Still Walking','UCD9clPtpOTsz7PPrm2JpafQ','4K 60FPS','2026-05-29T15:00:49Z','Izmir','Turkey','{"id":"qcuH8m1uMOo","title":"Don''t Miss This Sunset in Izmir: Cozy Walk From Coast to Alsancak Backstreets 🌅 | Turkey 4K","description":"Experience the magical transition of Izmir from a golden sunset to the vibrant, hidden nightlife of Alsancak in full 4K 60fps. The journey begins on the iconic Kordon coastline during the golden hour. Everyone is in a total chill mood—some are freezing the moment with their cameras, some are taking a peaceful evening walk, while others are relaxing on the grass, enjoying the sunset vibe from every angle. After capturing the beautiful seaside ambience and the lively beachfront restaurants, we head deep into the heart of the city. As you walk through the streets, you will instantly feel Izmir’s genetic holiday vibe. Soon, we arrive at the most famous and crowded avenue of the city: Kibris Sehitleri Avenue. The energy here is unmatched! From this bustling main street, we dive into the fascinating maze of Alsancak''s side streets (alleys). Moving left and right through these passages, we discover the real soul of the city: taverns, hidden cafe-bars, lively crowds, and sudden pockets of serene silence. Finally, the walk concludes with a magnificent urban contrast—the historic Alsancak Train Station standing proud against the newly built, illuminated modern residences, perfectly captured just as the city tram passes by. No talking, no narration—just pure real-time walking and natural ambient city sounds. still walking 👣 📍 Location: Alsancak, İzmir, Turkey 📅 Date: May 28, 2026 (Thursday) 🕓 Time: 8:00 PM 🌡️ Temperature: 21°C continue walking here: 👉https://www.youtube.com/playlist?list=PLe0tLqhfoJ0lD4ABpCnNmKAxMpHq607gz from an earlier time: 👉 https://www.youtube.com/playlist?list=PLe0tLqhfoJ0kA5DZ-hMOT5mX-rHSVN8EK Contact: izmirexplorer@gmail.com #izmir #alsancak #walkingtour #sunsetwalk #turkeytravel #eveningwalk","thumbnail":"https://i.ytimg.com/vi/qcuH8m1uMOo/maxresdefault.jpg","category":"Walking Tours","city":"Izmir","country":"Turkey","channel":"Still Walking","channelTitle":"Still Walking","channelId":"UCD9clPtpOTsz7PPrm2JpafQ","badge":"4K 60FPS","publishedAt":"2026-05-29T15:00:49Z","viewCount":3646,"durationSeconds":3089,"admission":{"version":3,"status":"channel-candidate","source":"channel-archive","mode":"CITY"}}','1');
INSERT OR IGNORE INTO videos (id,title,description,thumbnail,category,channel,channel_title,channel_id,badge,published_at,city,country,raw_json,active) VALUES ('cXGCB_0QLo0','A Sunny Day in İzmir: A Walking Tour of Konak Square & Waterfront (4K 60fps)','İzmir walking tour Konak district November 14, 2023 2 pm Tuesday Temperature: +23 ℃ A Sunny Day in İzmir: A Walking Tour of Konak Square & Waterfront (4K 60fps) Contact: izmirexplorer@gmail.com #izmir #turkey #walkingtour #konak #sunnyday #citylife #streettour','https://i.ytimg.com/vi/cXGCB_0QLo0/maxresdefault.jpg','Walking Tours','Still Walking','Still Walking','UCD9clPtpOTsz7PPrm2JpafQ','4K 60FPS','2023-11-15T12:01:44Z','Izmir','Turkey','{"id":"cXGCB_0QLo0","title":"A Sunny Day in İzmir: A Walking Tour of Konak Square & Waterfront (4K 60fps)","description":"İzmir walking tour Konak district November 14, 2023 2 pm Tuesday Temperature: +23 ℃ A Sunny Day in İzmir: A Walking Tour of Konak Square & Waterfront (4K 60fps) Contact: izmirexplorer@gmail.com #izmir #turkey #walkingtour #konak #sunnyday #citylife #streettour","thumbnail":"https://i.ytimg.com/vi/cXGCB_0QLo0/maxresdefault.jpg","category":"Walking Tours","city":"Izmir","country":"Turkey","channel":"Still Walking","channelTitle":"Still Walking","channelId":"UCD9clPtpOTsz7PPrm2JpafQ","badge":"4K 60FPS","publishedAt":"2023-11-15T12:01:44Z","viewCount":3632,"durationSeconds":1880,"admission":{"version":3,"status":"channel-candidate","source":"channel-archive","mode":"CITY"}}','1');
INSERT OR IGNORE INTO videos (id,title,description,thumbnail,category,channel,channel_title,channel_id,badge,published_at,city,country,raw_json,active) VALUES ('0EnYKMtdhUU','Izmir’s Hidden Fairy Tale: Stunning 4K Kemeraltı Walking Tour 🇹🇷','Step into a hidden fairy tale in the heart of Izmir. In this 4K 60fps walking tour, we explore the enchanting and picturesque backstreets of Kemeraltı, one of the oldest and largest open-air bazaars in the world. From vibrant, colorful passages to mysterious abandoned structures that tell stories of centuries past, this walk captures the unique soul and energy of Old Town Izmir. Experience the contrast between the bustling main paths and the peaceful, quiet alleys. Every corner reveals a new architectural marvel, a splash of color, or a fragment of history. This is more than just a walk; it’s an immersive ASMR experience designed to let you feel the authentic atmosphere of Turkey’s most historic marketplace. No talking, just the real sounds of the city. 📍 Key Highlights: ▪︎ The Picturesque Backstreets: Hidden gems that tourists often miss. ▪︎ Architectural Wonders: A mix of restored Ottoman heritage and poetic ruins. ▪︎ Authentic Atmosphere: The rhythmic sounds and vibrant colors of local life. ▪︎ Cinematic Quality: Filmed in 4K 60fps with natural settings for an ultra-realistic feel. Izmir Walking Tour🚶‍♂️ Konak District🏛️ Date: December 15, 2025 (Monday) 📅 Time: 3 PM 🕓 Temperature: 20°C 🌡️ Camera: Dji Osmo Pocket 3 🎥 All Izmir walking tours here: Real Izmir Walking Tours 4K 🇹🇷 https://www.youtube.com/playlist?list=PLe0tLqhfoJ0kA5DZ-hMOT5mX-rHSVN8EK Contact: izmirexplorer@gmail.com #Izmir #Kemeraltı #WalkingTour #4KWalk #ASMR #TravelTurkey #CinematicWalk #OldTown #HiddenGem #TravelVlog #StreetPhotography #TurkishBazaar','https://i.ytimg.com/vi/0EnYKMtdhUU/maxresdefault.jpg','Walking Tours','Still Walking','Still Walking','UCD9clPtpOTsz7PPrm2JpafQ','4K 60FPS','2025-12-17T14:45:00Z','Izmir','Turkey','{"id":"0EnYKMtdhUU","title":"