INSERT OR IGNORE INTO videos (id,title,description,thumbnail,category,channel,channel_title,channel_id,badge,published_at,city,country,raw_json,active) VALUES ('oqTbWi-Gwaw','Izmir Bostanlı Walking Tour: Stunning 4K Streets & Local Market (Karşıyaka) 🇹🇷','Welcome to Bostanlı, Karşıyaka (Izmir, Turkey)! 🇹🇷 Join this relaxing 4K 60FPS walking tour through one of Izmir''s most modern and lively neighborhoods – Bostanlı. Experience real local daily life with natural sounds only (no commentary). We start with Izmir''s iconic seagulls chasing simit on the ferry, then explore the vibrant pedestrian street full of cafés, young people, and the modern tram. Next, dive into the huge Bostanlı Bazaar (Pazar) – fresh food, affordable clothing, and textile paradise! Finally, end with a peaceful seaside walk along Bostanlı Sahil with stunning sea views. Perfect for virtual travel, relaxation, or planning your trip to Izmir! 📽️ Filmed in stunning 4K 60FPS for immersive experience. Chapters: 00:00 Intro: Seagulls & Ferry Vibe 🥯 00:09 Best Street in Bostanlı: Tram, Cafés & Local Life 🚋 16:34 Bostanlı Bazaar: Vibrant Market Shopping & Food 🛍️ 31:35 Peaceful Seaside Walk & Sea Views 🌊 Subscribe for more 4K walking tours in Izmir and Turkey! 🔔 Turn on notifications! Izmir Walking Tour🚶‍♂️ Karşıyaka District🏛️ Bostanlı Neighborhood 🏘️ Date: November 19, 2025 (Wednesday) 📅 Time: 3 PM 🕓 Temperature: 23°C 🌡️ Camera: Dji Osmo Pocket 3 🎥 All Izmir walking tours here: Real Izmir Walking Tours 4K 🇹🇷 https://www.youtube.com/playlist?list=PLe0tLqhfoJ0kA5DZ-hMOT5mX-rHSVN8EK Contact: izmirexplorer@gmail.com #Izmir #Bostanlı #Karşıyaka #WalkingTour #Turkey #IzmirWalkingTour #BostanlıPazar #Izmir4K #TurkeyTravel #VirtualTour','https://i.ytimg.com/vi/oqTbWi-Gwaw/maxresdefault.jpg','Walking Tours','Still Walking','Still Walking','UCD9clPtpOTsz7PPrm2JpafQ','4K 60FPS','2025-11-21T17:45:10Z','Izmir','Turkey','{"id":"oqTbWi-Gwaw","title":"Izmir Bostanlı Walking Tour: Stunning 4K Streets & Local Market (Karş