INSERT OR IGNORE INTO videos (id,title,description,thumbnail,category,channel,channel_title,channel_id,badge,published_at,city,country,raw_json,active) VALUES ('kFhnbMc4mDs','Izmir Kemeraltı Hidden Backstreets Walking Tour: Historic Soul & Local Vibes 4K 60FPS 🇹🇷','Explore the hidden soul of Izmir with this 1-hour 4K walking tour through Kemeraltı''s secret backstreets! 🇹🇷 Unlike typical tourist routes, we dive deep into forgotten historic alleys, Ottoman architecture, hidden hans (caravanserais), street art, local life, and charming cafes tucked away from the main bazaar crowd. Experience the real, untouched Izmir: quiet narrow streets with stunning historic houses, vibrant yet peaceful local vibes, and the transition into the colorful Kemeraltı Bazaar chaos. Perfect for relaxation, virtual travel, or planning your Izmir trip. Natural sounds only (no commentary) – pure ASMR immersion! Filmed in stunning 4K 60FPS. Izmir Walking Tour🚶‍♂️ Konak District🏛️ Kemeraltı Bazaar 🛍️ 🏛️ 🏘️ Date: November 22, 2025 (Saturday) 📅 Time: 2 PM 🕓 Temperature: 23°C 🌡️ Camera: Dji Osmo Pocket 3 🎥 🎧 Relaxing ambient sounds! ✨ Loved it? LIKE 👍 SUBSCRIBE 🔔 & turn on notifications for more hidden Izmir walks! #Kemeraltı #IzmirWalkingTour #HiddenIzmir #KemeraltıBackstreets #IzmirHiddenGems #TurkeyWalkingTour #Izmir4K #KemeraltıHistoric #IzmirLocalLife #VirtualTourIzmir All Izmir walking tours here: Real Izmir Walking Tours 4K 🇹🇷 https://www.youtube.com/playlist?list=PLe0tLqhfoJ0kA5DZ-hMOT5mX-rHSVN8EK Contact: izmirexplorer@gmail.com','https://i.ytimg.com/vi/kFhnbMc4mDs/maxresdefault.jpg','Museums & Culture','Still Walking','Still Walking','UCD9clPtpOTsz7PPrm2JpafQ','4K 60FPS','2025-11-23T11:45:02Z','Izmir','Turkey','{"id":"kFhnbMc4mDs","title":"Izmir Kemeraltı Hidden Backstreets Walking Tour: Historic Soul & Local Vibes 4K 60FPS 🇹🇷","description":"Explore the hidden soul of Izmir with this 1-hour 4K walking tour through Kemeraltı''s secret backstreets! 🇹🇷 Unlike typical tourist routes, we di