INSERT OR IGNORE INTO videos (id,title,description,thumbnail,category,channel,channel_title,channel_id,badge,published_at,city,country,raw_json,active) VALUES ('NskoTr8gEKw','Alsancak, İzmir: From Busy Fair Crowds to Cozy Streets & Coast | Turkey 4K Walk 👣','Alsancak, İzmir: From Busy Fair Crowds to Cozy Streets & Coast | Turkey 4K Walk 👣 A walk through Alsancak, Izmir — from a crowded park gathering into quieter streets, all the way to the sea. Starting in Kültürpark during a busy public event — crowds, books, voices, a city gathered together in one place. The walk continues through Alsancak without a fixed plan, following the rhythm as the atmosphere gradually shifts. Streets open up. Cafes, corners, slower moments appear between the boulevards. The energy softens as the route moves closer to the Aegean coast — quieter, unhurried, letting the city unfold at its own pace. Filmed in Izmir with natural sounds, no commentary, and long uninterrupted sequences capturing everyday urban rhythm and the subtle contrast between lively gatherings and peaceful city moments. still walking 👣 📍 Kültürpark → Alsancak → Coast — Izmir, Türkiye ⏱ real time – no talking – natural sound continue walking here: 👉https://www.youtube.com/playlist?list=PLe0tLqhfoJ0lD4ABpCnNmKAxMpHq607gz from an earlier time: 👉 https://www.youtube.com/playlist?list=PLe0tLqhfoJ0kA5DZ-hMOT5mX-rHSVN8EK Contact: izmirexplorer@gmail.com #izmir #alsancak #walkingtour #streetwalk #turkey #citywalk #stillwalking','https://i.ytimg.com/vi/NskoTr8gEKw/maxresdefault.jpg','Walking Tours','Still Walking','Still Walking','UCD9clPtpOTsz7PPrm2JpafQ','4K 60FPS','2026-04-26T09:42:12Z','Izmir','Turkey','{"id":"NskoTr8gEKw","title":"Alsancak, İzmir: From Busy Fair Crowds to Cozy Streets & Coast | Turkey 4K Walk 👣","description":"Alsancak, İzmir: From Busy Fair Crowds to Cozy Streets & Coast | Turkey 4K Walk 👣 A walk through Alsancak, Izmir — from a crowded park gathering into quieter streets, all the way to the sea. Starting in Kültürpark during a busy public event — crowds, books, voices, a city gathered together in one place. The walk continues through Alsancak without a fixed plan, following the rhythm as the atmosphere gradually shifts. Streets open up. Cafes, corners, slower moments appear between the boulevards. The energy softens as the route moves closer to the Aegean coast — quieter, unhurried, letting the city unfold at its own pace. Filmed in Izmir with natural sounds, no commentary, and long uninterrupted sequences capturing everyday urban rhythm and the subtle contrast between lively gatherings and peaceful city moments. still walking 👣 📍 Kültürpark → Alsancak → Coast — Izmir, Türkiye ⏱ real time – no talking – natural sound continue walking here: 👉https://www.youtube.com/playlist?list=PLe0tLqhfoJ0lD4ABpCnNmKAxMpHq607gz from an earlier time: 👉 https://www.youtube.com/playlist?list=PLe0tLqhfoJ0kA5DZ-hMOT5mX-rHSVN8EK Contact: izmirexplorer@gmail.com #izmir #alsancak #walkingtour #streetwalk #turkey #citywalk #stillwalking","thumbnail":"https://i.ytimg.com/vi/NskoTr8gEKw/maxresdefault.jpg","category":"Walking Tours","city":"Izmir","country":"Turkey","channel":"Still Walking","channelTitle":"Still Walking","channelId":"UCD9clPtpOTsz7PPrm2JpafQ","badge":"4K 60FPS","publishedAt":"2026-04-26T09:42:12Z","viewCount":2557,"durationSeconds":3115,"admission":{"version":3,"status":"channel-candidate","source":"channel-archive","mode":"CITY"}}','1');
