INSERT OR IGNORE INTO videos (id,title,description,thumbnail,category,channel,channel_title,channel_id,badge,published_at,city,country,raw_json,active) VALUES ('r0GeV_8CJzA','Izmir, Turkey: From Quiet Foothill Streets to Crowds & Metro | Balçova 4K Walking Tour 👣','Izmir, Turkey: From Quiet Foothill Streets to Crowds & Metro | Balçova 4K Walking Tour 👣 Join me for an immersive walking tour through the dual soul of Balçova, Izmir. We begin where the mountain breeze meets the city, exploring the spacious and breezy residential streets above Sakarya Street. Feel the peaceful isolation of the slopes as our 4K walking tour captures the mountains presence guarding the district. The journey takes a vibrant turn as we dive into the rhythmic chaos of Ata Street. In contrast to the airy foothills, this narrow, bustling corridor is the heart of the neighborhood—a perfect spot for a crowded street walk. Experience the nostalgic "mahalle" (neighborhood) vibe with its local shops and heavy single-lane traffic. Finally, we escape the heat and dive underground to the Balçova Metro Station for a cinematic finale. No commentary, just the raw pulse and urban rhythms of Izmir. still walking 👣 📍 Balçova, Izmir, Turkey continue walking here: 👉https://www.youtube.com/playlist?list=PLe0tLqhfoJ0lD4ABpCnNmKAxMpHq607gz from an earlier time: 👉 https://www.youtube.com/playlist?list=PLe0tLqhfoJ0kA5DZ-hMOT5mX-rHSVN8EK Contact: izmirexplorer@gmail.com #izmir #balçova #walkingtour #stillwalking #turkey #4kwalk #izmirmetro #citywalk','https://i.ytimg.com/vi/r0GeV_8CJzA/maxresdefault.jpg','Walking Tours','Still Walking','Still Walking','UCD9clPtpOTsz7PPrm2JpafQ','4K 60FPS','2026-05-06T14:30:44Z','Izmir','Turkey','{"id":"r0GeV_8CJzA","title":"Izmir, Turkey: From Quiet Foothill Streets to Crowds & Metro | Balçova 4K Walking Tour 👣","description":"Izmir, Turkey: From Quiet Foothill Streets to Crowds & Metro | Balçova 4K Walking Tour 👣 Join me for an immersive walking tour through the dual soul of Balçov