INSERT OR IGNORE INTO videos (id,title,description,thumbnail,category,channel,channel_title,channel_id,badge,published_at,city,country,raw_json,active) VALUES ('enuFmpx8Bhc','Izmir: Down the Stairs to a Completely Different Vibe | Turkey 4K Walk 👣 (Üçyol to Karataş)','Izmir: Down the Stairs to a Completely Different Vibe | Turkey 4K Walk 👣 (Üçyol to Karataş) A walk through Izmir, Turkey — from the upper streets of Üçyol down through stairs, narrow passages, and opening views toward the sea in Karataş. Starting above the city, the walk moves through wide open streets and slower corners. Then it shifts — streets narrow, stairs take over, and the view begins to open up as the sea gets closer. Without a fixed plan, the route drifts downhill through everyday Izmir, following the natural transition from the upper city down to the coast. Filmed with natural sounds, no commentary, and long uninterrupted sequences capturing the changing rhythm of streets, stairs, and urban life along the way. still walking 👣 📍 Üçyol → Karataş, Izmir, Türkiye continue walking here: 👉https://www.youtube.com/playlist?list=PLe0tLqhfoJ0lD4ABpCnNmKAxMpHq607gz from an earlier time: 👉 https://www.youtube.com/playlist?list=PLe0tLqhfoJ0kA5DZ-hMOT5mX-rHSVN8EK Contact: izmirexplorer@gmail.com #izmir #walkingtour #citywalk #turkey #stillwalking #staircase','https://i.ytimg.com/vi/enuFmpx8Bhc/maxresdefault.jpg','Walking Tours','Still Walking','Still Walking','UCD9clPtpOTsz7PPrm2JpafQ','4K 60FPS','2026-04-22T14:30:35Z','Izmir','Turkey','{"id":"enuFmpx8Bhc","title":"Izmir: Down the Stairs to a Completely Different Vibe | Turkey 4K Walk 👣 (Üçyol to Karataş)","description":"Izmir: Down the Stairs to a Completely Different Vibe | Turkey 4K Walk 👣 (Üçyol to Karataş) A walk through Izmir, Turkey — from the upper streets of Üçyol down through stairs, narrow passages, and opening views toward the sea in Karataş. Starting above the city, the walk moves through wide open streets and slower corners. Then it shifts — 