INSERT OR IGNORE INTO videos (id,title,description,thumbnail,category,channel,channel_title,channel_id,badge,published_at,city,country,raw_json,active) VALUES ('V-d7uE5umn4','Alsancak Arka Sokakları | Still Walking','Wandering through the backstreets of the city — no rush, no destination. Hidden cafés, silent walls, abandoned houses, street cats and passing strangers… This is not a tour. This is a state of being. In the middle of the crowd, I stop. Life keeps flowing. 📍 Location: Alsancak, İzmir ⏱ Real time • No talking • Natural sound 👣 Still Walking — continue walking here: 👉https://www.youtube.com/playlist?list=PLe0tLqhfoJ0lD4ABpCnNmKAxMpHq607gz from an earlier time: 👉 https://www.youtube.com/playlist?list=PLe0tLqhfoJ0kA5DZ-hMOT5mX-rHSVN8EK Contact: izmirexplorer@gmail.com — #stillwalking #backstreets #alsancak #izmir #citywalk #urbansilence #ambientwalk #walkingmeditation #urbanpoetry #streetphotography #izmirlife','https://i.ytimg.com/vi/V-d7uE5umn4/maxresdefault.jpg','Walking Tours','Still Walking','Still Walking','UCD9clPtpOTsz7PPrm2JpafQ','4K 60FPS','2026-03-01T08:30:08Z','Izmir','Turkey','{"id":"V-d7uE5umn4","title":"Alsancak Arka Sokakları | Still Walking","description":"Wandering through the backstreets of the city — no rush, no destination. Hidden cafés, silent walls, abandoned houses, street cats and passing strangers… This is not a tour. This is a state of being. In the middle of the crowd, I stop. Life keeps flowing. 📍 Location: Alsancak, İzmir ⏱ Real time • No talking • Natural sound 👣 Still Walking — continue walking here: 👉https://www.youtube.com/playlist?list=PLe0tLqhfoJ0lD4ABpCnNmKAxMpHq607gz from an earlier time: 👉 https://www.youtube.com/playlist?list=PLe0tLqhfoJ0kA5DZ-hMOT5mX-rHSVN8EK Contact: izmirexplorer@gmail.com — #stillwalking #backstreets #alsancak #izmir #citywalk #urbansilence #ambientwalk #walkingmeditation #urbanpoetry #streetphotography #izmirlife","thumbnail":"https://i.ytimg.com/vi/V-d7uE5umn4/maxresdefault.jpg","category":"Walking Tours","city":"Izmir","country":"Turkey","channel":"Still Walking","channelTitle":"Still Walking","channelId":"UCD9clPtpOTsz7PPrm2JpafQ","badge":"4K 60FPS","publishedAt":"2026-03-01T08:30:08Z","viewCount":2367,"durationSeconds":3185,"admission":{"version":3,"status":"channel-candidate","source":"channel-archive","mode":"CITY"}}','1');
