INSERT OR IGNORE INTO videos (id,title,description,thumbnail,category,channel,channel_title,channel_id,badge,published_at,city,country,raw_json,active) VALUES ('jQ_lrclTtX0','No Plan, Just Walking Through Izmir’s Alsancak | Turkey 4K Walk 👣','No Plan, Just Walking Through Izmir’s Alsancak | Turkey 4K Walk 👣 From the waterfront into the backstreets. No destination, no plan. This walk is about drifting—letting the city decide the route. We start at the coast and move inward, caught between the pulse of busy boulevards and the silence of forgotten alleys. In Alsancak, every corner opens into something unexpected: a hidden cafe, a sudden mural, or a narrow street that feels miles away from the modern city. One moment it''s crowded, the next it’s just you and the sound of your own footsteps. No narration, no music—just the raw, uninterrupted layers of İzmir. Just following wherever the streets lead next. still walking 👣 📍 Location: Alsancak, İzmir, Türkiye 🎧 Experience: 4K 60fps | Natural Sounds | Immersive Walk continue walking here: 👉https://www.youtube.com/playlist?list=PLe0tLqhfoJ0lD4ABpCnNmKAxMpHq607gz from an earlier time: 👉 https://www.youtube.com/playlist?list=PLe0tLqhfoJ0kA5DZ-hMOT5mX-rHSVN8EK Contact: izmirexplorer@gmail.com #alsancak #izmir #walkingtour #citywalk #stillwalking #turkey','https://i.ytimg.com/vi/jQ_lrclTtX0/maxresdefault.jpg','Walking Tours','Still Walking','Still Walking','UCD9clPtpOTsz7PPrm2JpafQ','4K 60FPS','2026-04-19T11:30:28Z','Izmir','Turkey','{"id":"jQ_lrclTtX0","title":"No Plan, Just Walking Through Izmir’s Alsancak | Turkey 4K Walk 👣","description":"No Plan, Just Walking Through Izmir’s Alsancak | Turkey 4K Walk 👣 From the waterfront into the backstreets. No destination, no plan. This walk is about drifting—letting the city decide the route. We start at the coast and move inward, caught between the pulse of busy boulevards and the silence of forgotten alleys. In Alsancak, every corner opens into something unexpected: a hidden cafe, a sudden mural, or a narrow street that feels miles away from the modern city. One moment it''s crowded, the next it’s just you and the sound of your own footsteps. No narration, no music—just the raw, uninterrupted layers of İzmir. Just following wherever the streets lead next. still walking 👣 📍 Location: Alsancak, İzmir, Türkiye 🎧 Experience: 4K 60fps | Natural Sounds | Immersive Walk continue walking here: 👉https://www.youtube.com/playlist?list=PLe0tLqhfoJ0lD4ABpCnNmKAxMpHq607gz from an earlier time: 👉 https://www.youtube.com/playlist?list=PLe0tLqhfoJ0kA5DZ-hMOT5mX-rHSVN8EK Contact: izmirexplorer@gmail.com #alsancak #izmir #walkingtour #citywalk #stillwalking #turkey","thumbnail":"https://i.ytimg.com/vi/jQ_lrclTtX0/maxresdefault.jpg","category":"Walking Tours","city":"Izmir","country":"Turkey","channel":"Still Walking","channelTitle":"Still Walking","channelId":"UCD9clPtpOTsz7PPrm2JpafQ","badge":"4K 60FPS","publishedAt":"2026-04-19T11:30:28Z","viewCount":2280,"durationSeconds":3039,"admission":{"version":3,"status":"channel-candidate","source":"channel-archive","mode":"CITY"}}','1');
INSERT OR IGNORE INTO videos (id,title,description,thumbnail,category,channel,channel_title,channel_id,badge,published_at,city,country,raw_json,active) VALUES ('SjtJd6QE1R0','Izmir Local Walking Tour: Secret Stairway to Aegean Sea View from Üçyol to Konak 4K 🇹🇷','Experience 100% authentic local Izmir with this relaxing 4K walking tour from Üçyol to Konak! 🇹🇷 Start in the lively Üçyol Square with real daily life sounds – metro crowds, bus chatter, and a local woman singing Sibel Can''s "Lale Devri" surrounded by café-goers and pigeons. Then discover Izmir''s best-kept secret: a long, narrow hidden stairway with old buildings and stray cats, leading to a breathtaking narrow view of the Aegean Sea. The journey continues with a quiet, nostalgic walk through streets showcasing beautiful old Izmir architecture, ending at Konak Metro Underpass. No talking – just natural sounds for pure immersion. Perfect for virtual travel or feeling the real local vibe! Filmed in stunning 4K. Izmir Walking Tour🚶‍♂️ Konak District🏛️ Date: November 25, 2025 (Tuesday) 📅 Time: 2 PM 🕓 Temperature: 23°C 🌡️ Camera: Dji Osmo Pocket 3 🎥 🎧 ASMR ambient sounds! ✨ Loved it? LIKE 👍 SUBSCRIBE 🔔 & turn on notifications for more hidden Izmir walks! #IzmirWalkingTour #ÜçyolKonak #IzmirLocalLife #HiddenIzmir #AegeanViewIzmir #IzmirSecretStairs #TurkeyWalkingTour #Izmir4K #IzmirRealLife #KonakIzmir All Izmir walking tours here: Real Izmir Walking Tours 4K 🇹🇷 https://www.youtube.com/playlist?list=PLe0tLqhfoJ0kA5DZ-hMOT5mX-rHSVN8EK Contact: izmirexplorer@gmail.com','https://i.ytimg.com/vi/SjtJd6QE1R0/maxresdefault.jpg','Walking Tours','Still Walking','Still Walking','UCD9clPtpOTsz7PPrm2JpafQ','4K 60FPS','2025-11-27T14:45:03Z','Izmir','Turkey','{"id":"SjtJd6QE1R0","title":"Izmir Local Walking Tour: Secret Stairway to Aegean Sea View from Üçyol to Konak 4K 🇹🇷","description":"Experience 100% authentic local Izmir with this relaxing 4K walking tour from Üçyol to Konak! 🇹🇷 Start in the lively Üçyol Square with rea