INSERT OR IGNORE INTO videos (id,title,description,thumbnail,category,channel,channel_title,channel_id,badge,published_at,city,country,raw_json,active) VALUES ('MqnK16QK9L4','Walking Through İzmir | From Basmane to Alsancak (4K)','This uninterrupted walk begins in İzmir’s historic Basmane district and slowly moves through changing streets, neighborhoods, and rhythms of daily life. Along the way, the city reveals its many layers — crowded passages, quiet side streets, aging buildings, busy markets, and sudden shifts in atmosphere. Without commentary or edits, the walk simply follows the street as it unfolds — allowing the contrasts, movements, and pauses of the city to speak for themselves. No narration. No cuts. Just the natural flow of walking through a city shaped by history, transition, and everyday life. 📍 Location: İzmir Konak, Turkey 📅 Date: January 28, 2026 (Wednesday) 🕓 Time: 3:00 PM 🌡️ Temperature: 16°C 🎥 Camera: DJI Osmo Pocket 3 🎞️ Mode: Normal 🎬 Resolution: 4K 🎧 Audio: Natural city sounds If this walk gave you a moment of calm, feel free to like, subscribe, or share it with someone who enjoys quiet exploration. Thanks for walking with me. Still walking. Explore all walking journeys here: 👉 https://www.youtube.com/playlist?list=PLe0tLqhfoJ0kA5DZ-hMOT5mX-rHSVN8EK Contact: izmirexplorer@gmail.com #stillwalking #Izmir #Basmane #Alsancak #WalkingTour #StreetWalk #NoTalking #SlowTravel','https://i.ytimg.com/vi/MqnK16QK9L4/maxresdefault.jpg','Walking Tours','Still Walking','Still Walking','UCD9clPtpOTsz7PPrm2JpafQ','4K 60FPS','2026-01-29T14:00:42Z','Izmir','Turkey','{"id":"MqnK16QK9L4","title":"Walking Through İzmir | From Basmane to Alsancak (4K)","description":"This uninterrupted walk begins in İzmir’s historic Basmane district and slowly moves through changing streets, neighborhoods, and rhythms of daily life. Along the way, the city reveals its many layers — crowded passages, quiet side streets, aging buildings, busy markets, and sudden shifts in atmosphere. Without commentary or edits, the walk simply follows the street as it unfolds — allowing the contrasts, movements, and pauses of the city to speak for themselves. No narration. No cuts. Just the natural flow of walking through a city shaped by history, transition, and everyday life. 📍 Location: İzmir Konak, Turkey 📅 Date: January 28, 2026 (Wednesday) 🕓 Time: 3:00 PM 🌡️ Temperature: 16°C 🎥 Camera: DJI Osmo Pocket 3 🎞️ Mode: Normal 🎬 Resolution: 4K 🎧 Audio: Natural city sounds If this walk gave you a moment of calm, feel free to like, subscribe, or share it with someone who enjoys quiet exploration. Thanks for walking with me. Still walking. Explore all walking journeys here: 👉 https://www.youtube.com/playlist?list=PLe0tLqhfoJ0kA5DZ-hMOT5mX-rHSVN8EK Contact: izmirexplorer@gmail.com #stillwalking #Izmir #Basmane #Alsancak #WalkingTour #StreetWalk #NoTalking #SlowTravel","thumbnail":"https://i.ytimg.com/vi/MqnK16QK9L4/maxresdefault.jpg","category":"Walking Tours","city":"Izmir","country":"Turkey","channel":"Still Walking","channelTitle":"Still Walking","channelId":"UCD9clPtpOTsz7PPrm2JpafQ","badge":"4K 60FPS","publishedAt":"2026-01-29T14:00:42Z","viewCount":2187,"durationSeconds":3463,"admission":{"version":3,"status":"channel-candidate","source":"channel-archive","mode":"CITY"}}','1');
