INSERT OR IGNORE INTO videos (id,title,description,thumbnail,category,channel,channel_title,channel_id,badge,published_at,city,country,raw_json,active) VALUES ('ggE4UmT786U','Karşıyaka, Izmir: How is Life Going on the Other Side of the City? | Turkey 4K Walk 👣','Karşıyaka, Izmir: How is Life Going on the Other Side of the City? | Turkey 4K Walk 👣 Starting at the waterfront, this walking tour moves through the busiest boulevard, then disappears into narrow side streets, back and forth for an hour. Beginning at the coast, the walk enters Karşıyaka''s main boulevard — crowds, noise, the full weight of the city moving together. Then comes a turn, and everything shifts. Narrow streets, slower air, a different kind of flow running parallel to the chaos just one block away. Wide to narrow, loud to quiet, open to tight — the same city, two completely different rhythms. This slow walking tour moves gently through it all, letting each street settle before the next one opens. The walk ends by sitting still for three minutes, watching the flow without moving through it. Filmed with natural sounds, no commentary, and long uninterrupted sequences, this ambient walking tour captures the contrast between Karşıyaka''s busy streets and its quieter side passages. still walking 👣 📍 Karşıyaka, Izmir, Türkiye walking in Izmir · karşıyaka walking tour · silent walk 4K continue walking here: 👉https://www.youtube.com/playlist?list=PLe0tLqhfoJ0lD4ABpCnNmKAxMpHq607gz from an earlier time: 👉 https://www.youtube.com/playlist?list=PLe0tLqhfoJ0kA5DZ-hMOT5mX-rHSVN8EK Contact: izmirexplorer@gmail.com #izmir #karsiyaka #walkingtour #streetwalk #turkey #stillwalking','https://i.ytimg.com/vi/ggE4UmT786U/maxresdefault.jpg','Walking Tours','Still Walking','Still Walking','UCD9clPtpOTsz7PPrm2JpafQ','4K 60FPS','2026-05-02T11:01:09Z','Izmir','Turkey','{"id":"ggE4UmT786U","title":"Karşıyaka, Izmir: How is Life Going on the Other Side of the City? | Turkey 4K Walk 👣","description":"Karşıyaka, Izmir: How is L