INSERT OR IGNORE INTO videos (id,title,description,thumbnail,category,channel,channel_title,channel_id,badge,published_at,city,country,raw_json,active) VALUES ('hziglq9M0i0','Life in the Streets of Bostanlı, İzmir | Turkey 4K Walking Tour 👣 (Midday Calm)','Life in the Streets of Bostanlı, İzmir | Turkey 4K Walking Tour 👣 The walk begins in a quiet side street leading toward Bostanlı’s iconic pedestrian avenue, where the relaxed rhythm of local life unfolds under a moody, gray afternoon sky. Experience a world that feels miles away, yet is just a short ferry ride from the city center. What to expect in this journey: • The Pulse: Cozy cafes and the gentle energy of everyday life in İzmir’s most relaxed coastal neighborhood. • The Hidden: A detour into silent backstreets, resting street cats, and birdsong echoing between buildings. • The Escape: Leaving the vibrant streets behind to reach the Bostanlı Ferry Pier, where the Aegean Sea opens up to the horizon. We conclude this relaxing 4K walk by watching a local ferry depart before boarding our own, quietly leaving this "different life" behind. still walking 👣 📍 Location: İzmir Bostanlı, Turkey 📅 Date: May 8, 2026 (Friday) 🕓 Time: 2:00 PM 🌡️ Temperature: 23°C continue walking here: 👉https://www.youtube.com/playlist?list=PLe0tLqhfoJ0lD4ABpCnNmKAxMpHq607gz from an earlier time: 👉 https://www.youtube.com/playlist?list=PLe0tLqhfoJ0kA5DZ-hMOT5mX-rHSVN8EK Contact: izmirexplorer@gmail.com #izmir #bostanlı #walkingtour #turkey #4kwalk #citywalk #turkeytravel','https://i.ytimg.com/vi/hziglq9M0i0/maxresdefault.jpg','Walking Tours','Still Walking','Still Walking','UCD9clPtpOTsz7PPrm2JpafQ','4K 60FPS','2026-05-09T12:01:13Z','Izmir','Turkey','{"id":"hziglq9M0i0","title":"Life in the Streets of Bostanlı, İzmir | Turkey 4K Walking Tour 👣 (Midday Calm)","description":"Life in the Streets of Bostanlı, İzmir | Turkey 4K Walking Tour 👣 The walk begins in a quiet side street leading toward Bostanlı’s iconic pedestrian avenue, where the relaxed rhythm of local life unfolds under a moody, gray afternoon sky. Experience a world that feels miles away, yet is just a short ferry ride from the city center. What to expect in this journey: • The Pulse: Cozy cafes and the gentle energy of everyday life in İzmir’s most relaxed coastal neighborhood. • The Hidden: A detour into silent backstreets, resting street cats, and birdsong echoing between buildings. • The Escape: Leaving the vibrant streets behind to reach the Bostanlı Ferry Pier, where the Aegean Sea opens up to the horizon. We conclude this relaxing 4K walk by watching a local ferry depart before boarding our own, quietly leaving this \"different life\" behind. still walking 👣 📍 Location: İzmir Bostanlı, Turkey 📅 Date: May 8, 2026 (Friday) 🕓 Time: 2:00 PM 🌡️ Temperature: 23°C continue walking here: 👉https://www.youtube.com/playlist?list=PLe0tLqhfoJ0lD4ABpCnNmKAxMpHq607gz from an earlier time: 👉 https://www.youtube.com/playlist?list=PLe0tLqhfoJ0kA5DZ-hMOT5mX-rHSVN8EK Contact: izmirexplorer@gmail.com #izmir #bostanlı #walkingtour #turkey #4kwalk #citywalk #turkeytravel","thumbnail":"https://i.ytimg.com/vi/hziglq9M0i0/maxresdefault.jpg","category":"Walking Tours","city":"Izmir","country":"Turkey","channel":"Still Walking","channelTitle":"Still Walking","channelId":"UCD9clPtpOTsz7PPrm2JpafQ","badge":"4K 60FPS","publishedAt":"2026-05-09T12:01:13Z","viewCount":2154,"durationSeconds":3444,"admission":{"version":3,"status":"channel-candidate","source":"channel-archive","mode":"CITY"}}','1');
