INSERT OR IGNORE INTO videos (id,title,description,thumbnail,category,channel,channel_title,channel_id,badge,published_at,city,country,raw_json,active) VALUES ('omNBMcON5KI','Her Köşe Başında Başka Bir İzmir | Still Walking','Every turn reveals a different layer of the city. This 4K Still Walking film begins underground at Çankaya Metro — where ancient remains quietly exist beside modern transit — and slowly rises into İzmir’s changing streets. From Ottoman-era boulevards to narrow backstreets filled with fashion ateliers, from historic churches hidden between modern buildings to unexpected views of the sea, this walk moves through contrasts without forcing them. Each crossing leads to a different rhythm. Each street holds a different atmosphere. Modern and old. Silent and alive. Dense and open. The journey ends in the calm greenery of Kültürpark — after passing through districts that rarely sit still. No narration. No music. Just the city — unfolding layer by layer. 📍 Location: Çankaya, İzmir, Türkiye 🎥 Camera: DJI Osmo Pocket 3 🎞️ Mode: Normal 🎬 Resolution: 4K 🎧 Audio: Natural city sounds If this walk gave you a moment of calm, feel free to like, subscribe, or share it with someone who enjoys quiet exploration. Thanks for walking with me. Still walking. continue walking here: 👉https://www.youtube.com/playlist?list=PLe0tLqhfoJ0lD4ABpCnNmKAxMpHq607gz from an earlier time: 👉 https://www.youtube.com/playlist?list=PLe0tLqhfoJ0kA5DZ-hMOT5mX-rHSVN8EK Contact: izmirexplorer@gmail.com #StillWalking #Izmir #WalkingTour #CityWalk #UrbanExploration #Turkey #SlowTravel #StreetWalk #NoTalking #4KWalk','https://i.ytimg.com/vi/omNBMcON5KI/maxresdefault.jpg','Walking Tours','Still Walking','Still Walking','UCD9clPtpOTsz7PPrm2JpafQ','4K 60FPS','2026-02-11T11:48:14Z','Izmir','Turkey','{"id":"omNBMcON5KI","title":"Her Köşe Başında Başka Bir İzmir | Still Walking","description":"Every turn reveals a different layer of the city. This 4K Still Walking film begins underground at Çankaya Metro — where ancient remains quietly exist beside modern transit — and slowly rises into İzmir’s changing streets. From Ottoman-era boulevards to narrow backstreets filled with fashion ateliers, from historic churches hidden between modern buildings to unexpected views of the sea, this walk moves through contrasts without forcing them. Each crossing leads to a different rhythm. Each street holds a different atmosphere. Modern and old. Silent and alive. Dense and open. The journey ends in the calm greenery of Kültürpark — after passing through districts that rarely sit still. No narration. No music. Just the city — unfolding layer by layer. 📍 Location: Çankaya, İzmir, Türkiye 🎥 Camera: DJI Osmo Pocket 3 🎞️ Mode: Normal 🎬 Resolution: 4K 🎧 Audio: Natural city sounds If this walk gave you a moment of calm, feel free to like, subscribe, or share it with someone who enjoys quiet exploration. Thanks for walking with me. Still walking. continue walking here: 👉https://www.youtube.com/playlist?list=PLe0tLqhfoJ0lD4ABpCnNmKAxMpHq607gz from an earlier time: 👉 https://www.youtube.com/playlist?list=PLe0tLqhfoJ0kA5DZ-hMOT5mX-rHSVN8EK Contact: izmirexplorer@gmail.com #StillWalking #Izmir #WalkingTour #CityWalk #UrbanExploration #Turkey #SlowTravel #StreetWalk #NoTalking #4KWalk","thumbnail":"https://i.ytimg.com/vi/omNBMcON5KI/maxresdefault.jpg","category":"Walking Tours","city":"Izmir","country":"Turkey","channel":"Still Walking","channelTitle":"Still Walking","channelId":"UCD9clPtpOTsz7PPrm2JpafQ","badge":"4K 60FPS","publishedAt":"2026-02-11T11:48:14Z","viewCount":1976,"durationSeconds":3705,"admission":{"version":3,"status":"channel-candidate","source":"channel-archive","mode":"CITY"}}','1');
INSERT OR IGNORE INTO videos (id,title,description,thumbnail,category,channel,channel_title,channel_id,badge,published_at,city,country,raw_json,active) VALUES ('mqif1JTL9lE','What’s Really Inside Izmir’s Local Neighborhoods? | Turkey 4K Walking Tour 👣 (Çamdibi)','What’s Really Inside Izmir’s Local Neighborhoods? 👣 Ever wondered what lies beyond the famous coastlines and tourist plazas of İzmir? Today, we dive deep into the real streets of Çamdibi to see the city''s true face. The journey begins with a distant gaze at the rising glass towers, before a sudden zoom-out leads us into the heart of a narrow, seemingly endless alley. For 15 minutes, we navigate a world where the sky is just a thin line between buildings—a labyrinth of old streets that feels like a trip back in time. As the path unfolds, the contrast of İzmir''s Çamdibi reveals itself. From rugged, sidewalk-less avenues where pedestrians fight for space, to hidden residential corners filled with local vibes, we witness a district caught between its past and a luxury future. The most unexpected turn happens at the end: lured by the signs of traditional taverns (meyhane), a sudden detour leads us into the heart of an industrial car repair district—a raw and authentic finish to an unplanned urban exploration. What to expect in this journey: • 15 minutes of a narrow alley that feels like it has no end. • Moving from old neighborhood lanes to the shadow of giant luxury residences. • The Surprise: An accidental detour through tavern signs ending in the grit of the industrial zone. still walking 👣 📍 Location: İzmir Çamdibi, Turkey 📅 Date: May 11, 2026 (Monday) 🕓 Time: 2:00 PM 🌡️ Temperature: 23°C 🎧 Experience: 4K UHD, No Commentary, Natural City Sounds, Authentic Urban Exploration. continue walking here: 👉https://www.youtube.com/playlist?list=PLe0tLqhfoJ0lD4ABpCnNmKAxMpHq607gz from an earlier time: 👉 https://www.youtube.com/playlist?list=PLe0tLqhfoJ0kA5DZ-hMOT5mX-rHSVN8EK Contact: izmirexplorer@gmail.com #izmir #çamdibi #walkingtour #turkeytravel #citywalk #stillwalking','https://i.ytimg.com/vi/mqif1JTL9lE/maxresdefault.jpg','Walking Tours','Still Walking','Still Walking','UCD9clPtpOTsz7PPrm2JpafQ','4K 60FPS','2026-05-13T14:30:37Z','Izmir','Turkey','{"id":"mqif1JTL9lE","title":"What’s Really Inside Izmir’s Local Neighborhoods? | Turkey 4K Walking Tour 👣 (Çamdibi)","description":"What’s Really Inside Izmir’s Local Neighborhoods? 👣 Ever wondered what lies beyond the famous coastlines and tourist plazas of İzmir? Today, we dive deep into the real streets of Çamdibi to see the city''s true face. The journey begins with a distant gaze at the rising glass towers, before a sudden zoom-out leads us into the heart of a narrow, seemingly endless alley. For 15 minutes, we navigate a world where the sky is just a thin line between buildings—a labyrinth of old streets that feels like a trip back in time. As the path unfolds, the contrast of İzmir''s Çamdibi reveals itself. From rugged, sidewalk-less avenues where pedestrians fight for space, to hidden residential corners filled with local vibes, we witness a district caught between its past and a luxury future. The most unexpected turn happens at the end: lured by the signs of traditional taverns (meyhane), a sudden detour leads us into the heart of an industrial car repair district—a raw and authentic finish to an unplanned urban exploration. What to expect in this journey: • 15 minutes of a narrow alley that feels like it has no end. • Moving from old neighborhood lanes to the shadow of giant luxury residences. • The Surprise: An accidental detour through tavern signs ending in the grit of the industrial zone. still walking 👣 📍 Location: İzmir Çamdibi, Turkey 📅 Date: May 11, 2026 (Monday) 🕓 Time: 2:00 PM 🌡️ Temperature: 23°C 🎧 Experience: 4K UHD, No Commentary, Natural City Sounds, Authentic Urban Exploration. continue walking here: 👉https://www.youtube.com/playlist?list=PLe0tLqhfoJ0lD4ABpCnNmKAxMpHq607gz from an earlier time: 👉 https: