INSERT OR IGNORE INTO videos (id,title,description,thumbnail,category,channel,channel_title,channel_id,badge,published_at,city,country,raw_json,active) VALUES ('JT0cVjrjpCw','Shall We Get Lost in İzmir: Kemeraltı''s Hidden Streets & Bazaar Maze | Turkey 4K Walk 👣','Shall We Get Lost in İzmir: Kemeraltı''s Hidden Streets & Bazaar Maze | Turkey 4K Walk 👣 Experience an immersive 4K walking tour through the historic Kemeraltı Bazaar in Izmir, Turkey. This real-time city walk explores the legendary maze-like streets, capturing the striking contrast between crowded market paths and the deep silence of hidden, abandoned back alleys. Lost in the same streets, again and again. Crowds, silence, and narrow paths that lead nowhere—then suddenly, an open space. Nothing planned, just following what appears. A quiet, atmospheric journey through the heart of Kemeraltı. If you''re looking for an authentic Izmir walking tour, this route takes you deep into the bazaar’s hidden corners and historic passages. Filmed in 4K 60fps, this video offers a silent walking experience with high-quality natural ambient sounds and no commentary. still walking 👣 📍Location: Kemeraltı Bazaar, Izmir, Türkiye continue walking here: 👉https://www.youtube.com/playlist?list=PLe0tLqhfoJ0lD4ABpCnNmKAxMpHq607gz from an earlier time: 👉 https://www.youtube.com/playlist?list=PLe0tLqhfoJ0kA5DZ-hMOT5mX-rHSVN8EK Contact: izmirexplorer@gmail.com #izmir #walkingtour #kemeraltı #4kwalk #turkey #travelturkey','https://i.ytimg.com/vi/JT0cVjrjpCw/maxresdefault.jpg','Walking Tours','Still Walking','Still Walking','UCD9clPtpOTsz7PPrm2JpafQ','4K 60FPS','2026-04-15T14:30:13Z','Izmir','Turkey','{"id":"JT0cVjrjpCw","title":"Shall We Get Lost in İzmir: Kemeraltı''s Hidden Streets & Bazaar Maze | Turkey 4K Walk 👣","description":"Shall We Get Lost in İzmir: Kemeraltı''s Hidden Streets & Bazaar Maze | Turkey 4K Walk 👣 Experience an immersive 4K walking tour through the historic Kemeraltı Bazaar in Izmir, Turkey. This real-time city 