INSERT OR IGNORE INTO videos (id,title,description,thumbnail,category,channel,channel_title,channel_id,badge,published_at,city,country,raw_json,active) VALUES ('326GAlTjDeM','Rainfall in İzmir: Alsancak Streets | Turkey 4K Walk 🌧 (Main Streets vs Quiet Alleys)','Moving between busy boulevards and empty alleys, the rain is the only constant during this walking tour. Starting in the heart of Alsancak, Izmir, this walk drifts without a fixed route, exploring the high contrast of the city. From wide avenues to narrow passages, from the rush of the main street to the stillness of deserted backstreets—the rain sets the pace, creating a rhythmic urban exploration. No plan, no commentary. Just the natural sound of umbrellas, wet pavement, and the city’s breath in the rain. • Route: Exploring the hidden corners of Alsancak • Vibe: High contrast, rhythmic, and calm • Format: 4K 60fps, No talking, No music (Pure ASMR) Still walking 👣 📍 Alsancak, Izmir, Türkiye continue walking here: 👉https://www.youtube.com/playlist?list=PLe0tLqhfoJ0lD4ABpCnNmKAxMpHq607gz from an earlier time: 👉 https://www.youtube.com/playlist?list=PLe0tLqhfoJ0kA5DZ-hMOT5mX-rHSVN8EK Contact: izmirexplorer@gmail.com #rainwalk #alsancak #izmir #turkey #walkingtour #citywalk','https://i.ytimg.com/vi/326GAlTjDeM/maxresdefault.jpg','Walking Tours','Still Walking','Still Walking','UCD9clPtpOTsz7PPrm2JpafQ','RAIN 4K','2026-04-04T08:30:02Z','Izmir','Turkey','{"id":"326GAlTjDeM","title":"Rainfall in İzmir: Alsancak Streets | Turkey 4K Walk 🌧 (Main Streets vs Quiet Alleys)","description":"Moving between busy boulevards and empty alleys, the rain is the only constant during this walking tour. Starting in the heart of Alsancak, Izmir, this walk drifts without a fixed route, exploring the high contrast of the city. From wide avenues to narrow passages, from the rush of the main street to the stillness of deserted backstreets—the rain sets the pace, creating a rhythmic urban exploration. No plan, no commentary. Just the na