INSERT OR IGNORE INTO videos (id,title,description,thumbnail,category,channel,channel_title,channel_id,badge,published_at,city,country,raw_json,active) VALUES ('Lc01D7FTKZc','Izmir Turkey: We Walk To The Rally Area, April 30, 2023 | 4K 60fps Walking Tour','We walk to the rally area hours before the big rally. İzmir walking tour Konak district April 30, 2023 1 pm sunday Temperature: +23 ℃ Contact: izmirexplorer@gmail.com #izmir #turkey #walkingtour','https://i.ytimg.com/vi/Lc01D7FTKZc/maxresdefault.jpg','Walking Tours','Still Walking','Still Walking','UCD9clPtpOTsz7PPrm2JpafQ','4K 60FPS','2023-05-01T11:03:08Z','Izmir','Turkey','{"id":"Lc01D7FTKZc","title":"Izmir Turkey: We Walk To The Rally Area, April 30, 2023 | 4K 60fps Walking Tour","description":"We walk to the rally area hours before the big rally. İzmir walking tour Konak district April 30, 2023 1 pm sunday Temperature: +23 ℃ Contact: izmirexplorer@gmail.com #izmir #turkey #walkingtour","thumbnail":"https://i.ytimg.com/vi/Lc01D7FTKZc/maxresdefault.jpg","category":"Walking Tours","city":"Izmir","country":"Turkey","channel":"Still Walking","channelTitle":"Still Walking","channelId":"UCD9clPtpOTsz7PPrm2JpafQ","badge":"4K 60FPS","publishedAt":"2023-05-01T11:03:08Z","viewCount":1789,"durationSeconds":2127,"admission":{"version":3,"status":"channel-candidate","source":"channel-archive","mode":"CITY"}}','1');
INSERT OR IGNORE INTO videos (id,title,description,thumbnail,category,channel,channel_title,channel_id,badge,published_at,city,country,raw_json,active) VALUES ('fPz3hVcoYjw','Bornova, Izmir: From Industrial Streets to Secret Luxury Neighborhoods | Turkey 4K Walk 👣','Bornova, Izmir: From Industrial Streets to Secret Luxury Neighborhoods | Turkey 4K Walk 👣 After getting off at the Sanayi metro station in Bornova, I entered a long graffiti-covered road that I had my eye on, but had no idea where it led. This unexpected Bornova, Izmir 4K walking tour quickly turned into one of the most interesting urban walks I’ve done in Turkey. The road was full of trees and at the end, I suddenly found myself in a huge auto industrial area. What a surprise! 🔥 Even with all the noise, there’s a weird sense of peace here. Guys love industrial zones anyway 😄 As I continued walking, completely unaware of the massive vibe shift coming, the industrial area ended and luxury buildings + tavernas started appearing. It was still early, so the tavernas were empty. With every step, the atmosphere changed completely. The contrast between old and new buildings was amazing. But the real surprise was still waiting… After seeing the highway flowing over the viaducts, I turned left and passed through a modern plaza. A while later, at one corner I got stuck deciding which way to go. I finally chose a direction… and luckily, it was the right one 😉 This Izmir street walking video captures a very different side of modern Turkey — from graffiti streets and industrial scenery to stylish restaurant areas and luxury urban neighborhoods. The rest? Watch the video… Enjoy the walk! 👣 📍 Location: Bornova, İzmir, Turkey 📅 Date: May 18, 2026 (Monday) 🕓 Time: 2:00 PM 🌡️ Temperature: 23°C continue walking here: 👉https://www.youtube.com/playlist?list=PLe0tLqhfoJ0lD4ABpCnNmKAxMpHq607gz from an earlier time: 👉 https://www.youtube.com/playlist?list=PLe0tLqhfoJ0kA5DZ-hMOT5mX-rHSVN8EK Contact: izmirexplorer@gmail.com #izmir #bornova #walkingtour #turkeytravel #citywalk #stillwalking','https://i.ytimg.com/vi/fPz3hVcoYjw/maxresdefault.jpg','Walking Tours','Still Walking','Still Walking','UCD9clPtpOTsz7PPrm2JpafQ','4K 60FPS','2026-05-19T14:30:20Z','Izmir','Turkey','{"id":"fPz3hVcoYjw","title":"Bornova, Izmir: From Industrial Streets to Secret Luxury Neighborhoods | Turkey 4K Walk 👣","description":"Bornova, Izmir: From Industrial Streets to Secret Luxury Neighborhoods | Turkey 4K Walk 👣 After getting off at the Sanayi metro station in Bornova, I entered a long graffiti-covered road that I had my eye on, but had no idea where it led. This unexpected Bornova, Izmir 4K walking tour quickly turned into one of the most interesting urban walks I’ve done in Turkey. The road was full of trees and at the end, I suddenly found myself in a huge auto industrial area. What a surprise! 🔥 Even with all the noise, there’s a weird sense of peace here. Guys love industrial zones anyway 😄 As I continued walking, completely unaware of the massive vibe shift coming, the industrial area ended and luxury buildings + tavernas started appearing. It was still early, so the tavernas were empty. With every step, the atmosphere changed completely. The contrast between old and new buildings was amazing. But the real surprise was still waiting… After seeing the highway flowing over the viaducts, I turned left and passed through a modern plaza. A while later, at one corner I got stuck deciding which way to go. I finally chose a direction… and luckily, it was the right one 😉 This Izmir street walking video captures a very different side of modern Turkey — from graffiti streets and industrial scenery to stylish restaurant areas and luxury urban neighborhoods. The rest? Watch the video… Enjoy the walk! 👣 📍 Location: Bornova, İzmir, Turkey 📅 Date: May 18, 2026 (Monday) 🕓 Time: 2:00 PM 🌡️ Temperature: 23°C continue walking here: 👉https://www.youtube.com/playlist?list=PLe0tLqhfoJ0lD4ABpCnNmKAxMpHq607gz from an earlier time: 👉 https://www.youtube.com/playlist?list=PLe0tLqhfoJ0kA5DZ-hMOT5mX-rHSVN8EK Contact: izmirexplorer@gmail.com #izmir #bornova #walkingtour #turkeytravel #citywalk #stillwalking","thumbnail":"https://i.ytimg.com/vi/fPz3hVcoYjw/maxresdefault.jpg","category":"Walking Tours","city":"Izmir","country":"Turkey","channel":"Still Walking","channelTitle":"Still Walking","channelId":"UCD9clPtpOTsz7PPrm2JpafQ","badge":"4K 60FPS","publishedAt":"2026-05-19T14:30:20Z","viewCount":1769,"durationSeconds":3795,"admission":{"version":3,"status":"channel-candidate","source":"channel-archive","mode":"CITY"}}','1');
