INSERT OR IGNORE INTO videos (id,title,description,thumbnail,category,channel,channel_title,channel_id,badge,published_at,city,country,raw_json,active) VALUES ('juoeqKPmv-0','İzmir''s Bayraklı: Skyscraper District and Everyday Streets (4K Walk) — Still Walking 👣','İzmir''s Bayraklı: Skyscraper District and Everyday Streets (4K Walk) — Still Walking 🇹🇷 Where old textures meet a rising skyline. Starting from a worn wall marked by time, this İzmir walking tour slowly reveals a different side of the city. As we drift through Bayraklı, the modern skyscrapers of the business district stand in contrast with the quiet streets and authentic residential areas. Hidden taverns, local corners, and unexpected views appear one by one in this 4K walk. No rush. No route. Just following what the streets offer in this urban exploration. Captured with natural ambient sounds and long, uninterrupted sequences to bring the real atmosphere of İzmir''s backstreets to your screen. Still Walking 👣 📍Location: İzmir, Bayraklı – Türkiye ⏱ Real time – No talking – Natural sound continue walking here: 👉https://www.youtube.com/playlist?list=PLe0tLqhfoJ0lD4ABpCnNmKAxMpHq607gz from an earlier time: 👉 https://www.youtube.com/playlist?list=PLe0tLqhfoJ0kA5DZ-hMOT5mX-rHSVN8EK Contact: izmirexplorer@gmail.com #izmir #bayrakli #walkingtour4k #streetwalk #stillwalking #turkey #citywalk','https://i.ytimg.com/vi/juoeqKPmv-0/maxresdefault.jpg','Walking Tours','Still Walking','Still Walking','UCD9clPtpOTsz7PPrm2JpafQ','4K 60FPS','2026-03-25T14:30:37Z','Izmir','Turkey','{"id":"juoeqKPmv-0","title":"İzmir''s Bayraklı: Skyscraper District and Everyday Streets (4K Walk) — Still Walking 👣","description":"İzmir''s Bayraklı: Skyscraper District and Everyday Streets (4K Walk) — Still Walking 🇹🇷 Where old textures meet a rising skyline. Starting from a worn wall marked by time, this İzmir walking tour slowly reveals a different side of the city. As we drift through Bayraklı, the modern skyscrapers of the business district stand in contrast with the quiet streets and authentic residential areas. Hidden taverns, local corners, and unexpected views appear one by one in this 4K walk. No rush. No route. Just following what the streets offer in this urban exploration. Captured with natural ambient sounds and long, uninterrupted sequences to bring the real atmosphere of İzmir''s backstreets to your screen. Still Walking 👣 📍Location: İzmir, Bayraklı – Türkiye ⏱ Real time – No talking – Natural sound continue walking here: 👉https://www.youtube.com/playlist?list=PLe0tLqhfoJ0lD4ABpCnNmKAxMpHq607gz from an earlier time: 👉 https://www.youtube.com/playlist?list=PLe0tLqhfoJ0kA5DZ-hMOT5mX-rHSVN8EK Contact: izmirexplorer@gmail.com #izmir #bayrakli #walkingtour4k #streetwalk #stillwalking #turkey #citywalk","thumbnail":"https://i.ytimg.com/vi/juoeqKPmv-0/maxresdefault.jpg","category":"Walking Tours","city":"Izmir","country":"Turkey","channel":"Still Walking","channelTitle":"Still Walking","channelId":"UCD9clPtpOTsz7PPrm2JpafQ","badge":"4K 60FPS","publishedAt":"2026-03-25T14:30:37Z","viewCount":1755,"durationSeconds":3482,"admission":{"version":3,"status":"channel-candidate","source":"channel-archive","mode":"CITY"}}','1');
INSERT OR IGNORE INTO videos (id,title,description,thumbnail,category,channel,channel_title,channel_id,badge,published_at,city,country,raw_json,active) VALUES ('egkznvAaQw4','İzmir’de İki Farklı Ruh Hâli Arasında Bir Yürüyüş | Yeşilyurt’tan Hatay’a | Still Walking','A walk between two different moods of İzmir. Starting from the narrow and busy streets of Yeşilyurt, where tall buildings, tight sidewalks and the constant flow of traffic create an intense urban feeling — not crowded, but compressed. After a quiet descent down the stairs, the atmosphere slowly opens up into the colorful and lively streets of Hatay. And in the final minutes, the rain arrives — softening everything, changing the rhythm of the walk. Same city, different layers. 📍 Route: Yeşilyurt → Hatay, İzmir, Türkiye 🎥 Camera: DJI Osmo Pocket 3 🎞️ Resolution: 4K 🎧 Audio: Natural city sounds (no music) If this walk gave you a moment of calm, feel free to like, subscribe, or share it with someone who enjoys quiet exploration. Thanks for walking with me. 👣 Still Walking continue walking here: 👉https://www.youtube.com/playlist?list=PLe0tLqhfoJ0lD4ABpCnNmKAxMpHq607gz from an earlier time: 👉 https://www.youtube.com/playlist?list=PLe0tLqhfoJ0kA5DZ-hMOT5mX-rHSVN8EK Contact: izmirexplorer@gmail.com #izmir #walkingvideo #rainwalk #citywalk #turkey #urbanwalking #asmrwalk #streetatmosphere #slowtv #hatayizmir #yesilyurt','https://i.ytimg.com/vi/egkznvAaQw4/maxresdefault.jpg','Walking Tours','Still Walking','Still Walking','UCD9clPtpOTsz7PPrm2JpafQ','4K 60FPS','2026-02-18T11:39:00Z','Izmir','Turkey','{"id":"egkznvAaQw4","title":"İzmir’de İki Farklı Ruh Hâli Arasında Bir Yürüyüş | Yeşilyurt’tan Hatay’a | Still Walking","description":"A walk between two different moods of İzmir. Starting from the narrow and busy streets of Yeşilyurt, where tall buildings, tight sidewalks and the constant flow of traffic create an intense urban feeling — not crowded, but compressed. After a quiet descent down the stairs, the atmosphere slowly opens up into the colorful and lively streets of Hatay. And in the final minutes, the rain arrives — softening everything, changing the rhythm of the walk. Same city, different layers. 📍 Route: Yeşilyurt → Hatay, İzmir, Türkiye 🎥 Camera: DJI Osmo Pocket 3 🎞️ Resolution: 4K 🎧 Audio: Natural city sounds (no music) If this walk gave you a moment of calm, feel free to like, subscribe, or share it with someone who enjoys quiet exploration. Thanks for walking with me. 👣 Still Walking continue walking here: 👉https://www.youtube.com/playlist?list=PLe0tLqhfoJ0lD4ABpCnNmKAxMpHq607gz from an earlier time: 👉 https://www.youtube.com/playlist?list=PLe0tLqhfoJ0kA5DZ-hMOT5mX-rHSVN8EK Contact: izmirexplorer@gmail.com #izmir #walkingvideo #rainwalk #citywalk #turkey #urbanwalking #asmrwalk #streetatmosphere #slowtv #hatayizmir #yesilyurt","thumbnail":"https://i.ytimg.com/vi/egkznvAaQw4/maxresdefault.jpg","category":"Walking Tours","city":"Izmir","country":"Turkey","channel":"Still Walking","channelTitle":"Still Walking","channelId":"UCD9clPtpOTsz7PPrm2JpafQ","badge":"4K 60FPS","publishedAt":"2026-02-18T11:39:00Z","viewCount":1729,"durationSeconds":3745,"admission":{"version":3,"status":"channel-candidate","source":"channel-archive","mode":"CITY"}}','1');
INSERT OR IGNORE INTO videos (id,title,description,thumbnail,category,channel,channel_title,channel_id,badge,published_at,city,country,raw_json,active) VALUES ('tjPJTy7hhcM','Izmir''s Inner Rhythm: A Calming City Walk with a Quiet Vibe 🇹🇷 [4K HDR]','📍 Izmir''s Inner Rhythm: A Calming City Walk with a Quiet Vibe 🇹🇷 [4K HDR] Experience İzmir like never before. Step away from the crowds and join us for a unique, one-hour walk right through the heart of the city center, revealing a remarkably tranquil side of this vibrant Aegean metropolis. This is not the İzmir you usually see; this is a deeper dive into the city''s quiet soul. 🎥 Technical Details & Production Filmed in Stunning Detail: Captured in 4K HDR (HLG) using the DJI Osmo Pocket 3. 🏙️ What to Expect on this Calming Walk: A Journey of Contrast: Witness the compelling harmony and stark contrast between Izmir''s historical architecture and its modern buildings standing side-by-side. This visual dialogue helps decode the city''s complex urban fabric. The Quiet Vibe: Despite being in the city center, the atmosphere is profoundly peaceful and soothing. The slow, rhythmic pace of the walk offers a truly calming experience. Atmospheric Views: The scenery shifts between a dramatic, sometimes grey, sometimes blue sky, reflecting on the unusually still and calm sea. Urban Details: Explore the tree-lined avenues, main streets, quieter side alleys, and hidden backstreets that give İzmir its unique character and spiritual depth. A New Perspective: This video is an insightful attempt to truly understand İzmir''s atmosphere, its architecture, and the sense of calm it holds within its core. 🎧 No talking — just natural sounds Izmir Walking Tour🚶‍♂️ Konak District🏛️ Date: December 1, 2025 (Monday) 📅 Time: 3 PM 🕓 Temperature: 19°C 🌡️ Camera: Dji Osmo Pocket 3 🎥 All Izmir walking tours here: Real Izmir Walking Tours 4K 🇹🇷 https://www.youtube.com/playlist?list=PLe0tLqhfoJ0kA5DZ-hMOT5mX-rHSVN8EK Contact: izmirexplorer@gmail.com #IzmirWalk #CityWalk #QuietVibe #4KHDR #HLG #OsmoPocket3 #UrbanExploration #IzmirCityCenter #SereneStroll #IzmirInnerRhythm #TurkeyWalk #SlowTV #TravelVideo #Izmir','https://i.ytimg.com/vi/tjPJTy7hhcM/maxresdefault.jpg','Walking Tours','Still Walking','Still Walking','UCD9clPtpOTsz7PPrm2JpafQ','4K 60FPS','2025-12-03T14:45:14Z','Izmir','Turkey','{"id":"tjPJTy7hhcM","title":"Izmir''s Inner Rhythm: A Calming City Walk with a Quiet Vibe 🇹🇷 [4K HDR]","description":"📍 Izmir''s Inner Rhythm: A Calming City Walk with a Quiet Vibe 🇹🇷 [4K HDR] Experience İzmir like never before. Step away from the crowds and join us for a unique, one-hour walk right through the heart of the city center, revealing a remarkably tranquil side of this vibrant Aegean metropolis. This is not the İzmir you usually see; this is a deeper dive into the city''s quiet soul. 🎥 Technical Details & Production Filmed in Stunning Detail: Captured in 4K HDR (HLG) using the DJI Osmo Pocket 3. 🏙️ What to Expect on this Calming Walk: A Journey of Contrast: Witness the compelling harmony and stark contrast between Izmir''s historical architecture and its modern buildings standing side-by-side. This visual dialogue helps decode the city''s complex urban fabric. The Quiet Vibe: Despite being in the city center, the atmosphere is profoundly peaceful and soothing. The slow, rhythmic pace of the walk offers a truly calming experience. Atmospheric Views: The scenery shifts between a dramatic, sometimes grey, sometimes blue sky, reflecting on the unusually still and calm sea. Urban Details: Explore the tree-lined avenues, main streets, quieter side alleys, and hidden backstreets that give İzmir its unique character and spiritual depth. A New Perspective: This video is an insightful attempt to truly understand İzmir''s atmosphere, its architecture, and the sense of calm it holds within its core. 🎧 No talking — just natural sounds Izmir Walking Tour🚶‍♂️ Konak District🏛️ Date: December 1, 2025 (Monday) 📅 Time: 3 PM 🕓 Temperature: 19°C 🌡️ Camera: Dji Osmo Pocket 3 🎥 All Izmir walking tours here: Real Izmir Walking Tours 4K 🇹🇷 https://www.youtube.com/playlist?list=PLe0tLqhfoJ0kA5DZ-hMOT5mX-rHSVN8EK Contact: izmirexplorer@gmail.com #IzmirWalk #CityWalk #QuietVibe #4KHDR #HLG #OsmoPocket3 #UrbanExploration #IzmirCityCenter #SereneStroll #IzmirInnerRhythm #TurkeyWalk #SlowTV #TravelVideo #Izmir","thumbnail":"https://i.ytimg.com/vi/tjPJTy7hhcM/maxresdefault.jpg","category":"Walking Tours","city":"Izmir","country":"Turkey","channel":"Still Walking","channelTitle":"Still Walking","channelId":"UCD9clPtpOTsz7PPrm2JpafQ","badge":"4K 60FPS","publishedAt":"2025-12-03T14:45:14Z","viewCount":1721,"durationSeconds":3676,"admission":{"version":3,"status":"channel-candidate","source":"channel-archive","mode":"CITY"}}','1');
INSERT OR IGNORE INTO videos (id,title,description,thumbnail,category,channel,channel_title,channel_id,badge,published_at,city,country,raw_json,active) VALUES ('qmmpuvEIdOY','İzmir Bostanlı Seaside Therapy – Eye of Sauron – 4K Sunset Walk 🇹🇷','Izmir Walking Tour 🚶‍♂️ Karşıyaka District | Bostanlı🏛️ Date: July 7, 2025 (Monday) 📅 Time: 8:45 PM 🕓 Temperature: 35°C 🌡️ 🎧 No talking — just natural sounds İzmir Bostanlı Seaside Therapy – Eye of Sauron – 4K Sunset Walk All Izmir walking tours here: Real Izmir Walking Tours 4K 🇹🇷 https://www.youtube.com/playlist?list=PLe0tLqhfoJ0kA5DZ-hMOT5mX-rHSVN8EK Contact: izmirexplorer@gmail.com #İzmir #turkey #bostanlı #walkingtour','https://i.ytimg.com/vi/qmmpuvEIdOY/maxresdefault.jpg','Beach Walking Tours','Still Walking','Still Walking','UCD9clPtpOTsz7PPrm2JpafQ','4K 60FPS','2025-07-09T15:45:07Z','Izmir','Turkey','{"id":"qmmpuvEIdOY","title":"İzmir Bostanlı Seaside Therapy – Eye of Sauron – 4K Sunset Walk 🇹🇷","description":"Izmir Walking Tour 🚶‍♂️ Karşıyaka District | Bostanlı🏛️ Date: July 7, 2025 (Monday) 📅 Time: 8:45 PM 🕓 Temperature: 35°C 🌡️ 🎧 No talking — just natural sounds İzmir Bostanlı Seaside Therapy – Eye of Sauron – 4K Sunset Walk All Izmir walking tours here: Real Izmir Walking Tours 4K 🇹🇷 https://www.youtube.com/playlist?list=PLe0tLqhfoJ0kA5DZ-hMOT5mX-rHSVN8EK Contact: izmirexplorer@gmail.com #İzmir #turkey #bostanlı #walkingtour","thumbnail":"https://i.ytimg.com/vi/qmmpuvEIdOY/maxresdefault.jpg","category":"Beach Walking Tours","city":"Izmir","country":"Turkey","channel":"Still Walking","channelTitle":"Still Walking","channelId":"UCD9clPtpOTsz7PPrm2JpafQ","badge":"4K 60FPS","publishedAt":"2025-07-09T15:45:07Z","viewCount":1718,"durationSeconds":2147,"admission":{"version":3,"status":"channel-candidate","source":"channel-archive","mode":"CITY"}}','1');
INSERT OR IGNORE INTO videos (id,title,description,thumbnail,category,channel,channel_title,channel_id,badge,published_at,city,country,raw_json,active) VALUES ('s2mn11qdMqY','Explore İzmir''s Karşıyaka: 4K HDR 25FPS Walk | 1-Hour Walking Tour & Frame Rate Test','THE 25FPS WALKING TEST | TECHNICAL FOCUS Welcome to a unique, 1-hour technical challenge! A common question among walking video creators is: "Can a city walk video truly be smooth and immersive when shot at only 25 frames per second (25fps)?" We set out to answer this by pushing the limits during our stunning 4K HDR walking tour through the vibrant streets of Karşıyaka, İzmir. This 60-minute video acts as a comprehensive Frame Rate Test, captured entirely on the powerful DJI Osmo Pocket 3. Our test specifically covers a wide range of challenging, real-world scenarios to provide a definitive answer: * Bright Sunlight vs. Deep Shade * Heavily Crowded Streets vs. Quiet, Secluded Paths * Tree-Lined Roads (to test complex motion/foliage) * Shooting Against the Sun (for backlight performance) Watch the full video to analyze the motion smoothness and cinematic feel of 25fps versus the standard 30fps/60fps. Let us know in the comments: Does 25fps deliver the required quality and immersion for high-end walking videos? --- DISCOVER KARŞIYAKA: FROM PELICANS TO PALM STREETS Beyond the technical test, this video is an immersive journey into one of İzmir’s most iconic districts: Karşıyaka. Often translated as "The Opposite Shore," Karşıyaka offers a captivating blend of bustling city life and tranquil coastal charm. The walk begins dramatically at the Fisherman''s Port, capturing the unique sight of numerous **Pelicans perched on the traditional fishing boats (taka)**—a classic Karşıyaka moment! We then plunge into the heart of the district, navigating the Crowded Central Streets before exploring the diverse character of its neighborhoods. Our route moves from the dense center to a parallel main artery, **Girne Boulevard**, before leading us into two distinct residential areas: * Nergiz: A look into a quieter, perhaps more traditional local life. * Bostanlı: Discover the modern, vibrant atmosphere of Bostanlı, famous for its lively coastal areas and contemporary feel. This 1-hour walk offers a complete picture of Karşıyaka, showcasing its unique contrast between the sea, the city center, and its neighboring communities. 🎧 No talking — just natural sounds ▶️ TIMESTAMPS: EXPLORE & TEST THE 25FPS --- 00:00 🦢 Pelicans at the Fisherman''s Port (A perfect Karşıyaka welcome!) 00:11 🏙️ Karşıyaka Central Square (The heart of the district: High crowd density test) 19:15 🌳 Transition Street: Berin Taşan (Shade and complex foliage test) 21:18 🛣️ Girne Boulevard (Navigating the main parallel artery) 24:42 🏡 Nergiz Neighborhood (A look into quiet, traditional local life) 45:35 🌊 Bostanlı Neighborhood (Discovering the modern, lively side of Karşıyaka) Izmir Walking Tour🚶‍♂️ Karşıyaka District🏛️ Date: December 12, 2025 (Friday) 📅 Time: 2 PM 🕓 Temperature: 20°C 🌡️ Camera: Dji Osmo Pocket 3 🎥 All Izmir walking tours here: Real Izmir Walking Tours 4K 🇹🇷 https://www.youtube.com/playlist?list=PLe0tLqhfoJ0kA5DZ-hMOT5mX-rHSVN8EK Contact: izmirexplorer@gmail.com #karşıyaka #izmir #walkingtour #4khdr #25fps #osmo #travel #turkey #bostanlı #nergiz #turkey','https://i.ytimg.com/vi/s2mn11qdMqY/maxresdefault.jpg','Walking Tours','Still Walking','Still Walking','UCD9clPtpOTsz7PPrm2JpafQ','4K 60FPS','2025-12-14T11:31:01Z','Izmir','Turkey','{"id":"s2mn11qdMqY","title":"Explore İzmir''s Karşıyaka: 4K HDR 25FPS Walk | 1-Hour Walking Tour & Frame Rate Test","description":"THE 25FPS WALKING TEST | TECHNICAL FOCUS Welcome to a unique, 1-hour technical challenge! A common question among walking video creators is: \"Can a city walk video truly be smooth and immersive when shot at only 25 frames per second (25fps)?\" We set out to answer this by pushing the limits during our stunning 4K HDR walking tour through the vibrant streets of Karşıyaka, İzmir. This 60-minute video acts as a comprehensive Frame Rate Test, captured entirely on the powerful DJI Osmo Pocket 3. Our test specifically covers a wide range of challenging, real-world scenarios to provide a definitive answer: * Bright Sunlight vs. Deep Shade * Heavily Crowded Streets vs. Quiet, Secluded Paths * Tree-Lined Roads (to test complex motion/foliage) * Shooting Against the Sun (for backlight performance) Watch the full video to analyze the motion smoothness and cinematic feel of 25fps versus the standard 30fps/60fps. Let us know in the comments: Does 25fps deliver the required quality and immersion for high-end walking videos? --- DISCOVER KARŞIYAKA: FROM PELICANS TO PALM STREETS Beyond the technical test, this video is an immersive journey into one of İzmir’s most iconic districts: Karşıyaka. Often translated as \"The Opposite Shore,\" Karşıyaka offers a captivating blend of bustling city life and tranquil coastal charm. The walk begins dramatically at the Fisherman''s Port, capturing the unique sight of numerous **Pelicans perched on the traditional fishing boats (taka)**—a classic Karşıyaka moment! We then plunge into the heart of the district, navigating the Crowded Central Streets before exploring the diverse character of its neighborhoods. Our route moves from the dense center to a parallel main artery, **Girne Boulevard**, before leading us into two distinct residential areas: * Nergiz: A look into a quieter, perhaps more traditional local life. * Bostanlı: Discover the modern, vibrant atmosphere of Bostanlı, famous for its lively coastal areas and contemporary feel. This 1-hour walk offers a complete picture of Karşıyaka, showcasing its unique contrast between the sea, the city center, and its neighboring communities. 🎧 No talking — just natural sounds ▶️ TIMESTAMPS: EXPLORE & TEST THE 25FPS --- 00:00 🦢 Pelicans at the Fisherman''s Port (A perfect Karşıyaka welcome!) 00:11 🏙️ Karşıyaka Central Square (The heart of the