INSERT OR IGNORE INTO videos (id,title,description,thumbnail,category,channel,channel_title,channel_id,badge,published_at,city,country,raw_json,active) VALUES ('89nC-dO1pzU','Still Walking Through Forgotten Streets | Time-Layered İzmir','Still Walking takes you through parts of the city where time feels suspended. In this 4K walking film, we wander through forgotten streets and quiet backstreets shaped by history — where everyday life unfolds without performance. From the stairs of İkiçeşmelik to abandoned mansions and weathered facades, each layer reveals a slower rhythm of the city. Our walk eventually reaches the restless energy of Kemeraltı Bazaar — where past and present collide in sound, movement, and flow. No narration. No music. Just walking through time layers. 📍 Location: İzmir Konak, Turkey 📅 Date: January 9, 2026 (Friday) 🕓 Time: 4 PM 🌡️ Temperature: 14°C 🎥 Camera: Dji Osmo Pocket 3 🎞️ Mode: Normal 🎬 Resolution: 4K 🎧 Audio: Natural city sounds If this walk gave you a moment of calm, feel free to like, subscribe, or share it with someone who enjoys quiet exploration. Thanks for walking with me. Still walking. Walking Through Alsancak in the Rain | Still Walking 👉 https://youtu.be/93khBKXLc7s Still Walking Karşıyaka | From Busy Streets to Hidden Corners 👉 https://youtu.be/g-JZvUHjzEI Explore all walking journeys here: 👉 https://www.youtube.com/playlist?list=PLe0tLqhfoJ0kA5DZ-hMOT5mX-rHSVN8EK Contact: izmirexplorer@gmail.com #stillwalking #Izmir #WalkingFilm #UrbanWalk #SlowTravel #CityAtmosphere #HiddenStreets','https://i.ytimg.com/vi/89nC-dO1pzU/maxresdefault.jpg','Walking Tours','Still Walking','Still Walking','UCD9clPtpOTsz7PPrm2JpafQ','4K 60FPS','2026-01-10T13:30:11Z','Izmir','Turkey','{"id":"89nC-dO1pzU","title":"Still Walking Through Forgotten Streets | Time-Layered İzmir","description":"Still Walking takes you through parts of the city where time feels suspended. In this 4K walking film, we wander through forgotten streets and quiet backstreets shap