INSERT OR IGNORE INTO videos (id,title,description,thumbnail,category,channel,channel_title,channel_id,badge,published_at,city,country,raw_json,active) VALUES ('ctQMAcBZpEA','Güzelyalı''ya Sessiz Bir Yürüyüş | Still Walking (4K)','A Quiet Walk into Güzelyalı | Still Walking (4K) No talking. No rush. Just walking. This uninterrupted walk begins in the back streets, slowly making its way into Güzelyalı. Along the way, the city reveals itself quietly — hidden corners, unexpected details, and a natural flow that leads, without effort, to the sea. This walk is not about reaching a place quickly, but about noticing what appears when you move slowly. 📍 Location: Güzelyalı, İzmir, Türkiye 🎥 Camera: DJI Osmo Pocket 3 🎞️ Mode: Normal 🎬 Resolution: 4K 🎧 Audio: Natural city sounds If this walk gave you a moment of calm, feel free to like, subscribe, or share it with someone who enjoys quiet exploration. Thanks for walking with me. Still walking. Explore all walking journeys here: 👉 https://www.youtube.com/playlist?list=PLe0tLqhfoJ0kA5DZ-hMOT5mX-rHSVN8EK Contact: izmirexplorer@gmail.com #StillWalking #Güzelyalı #Izmir #QuietWalk #WalkingTour #UrbanWalk #StreetWalk #NoTalking #CitySounds','https://i.ytimg.com/vi/ctQMAcBZpEA/maxresdefault.jpg','Walking Tours','Still Walking','Still Walking','UCD9clPtpOTsz7PPrm2JpafQ','4K 60FPS','2026-02-05T15:01:10Z','Izmir','Turkey','{"id":"ctQMAcBZpEA","title":"Güzelyalı''ya Sessiz Bir Yürüyüş | Still Walking (4K)","description":"A Quiet Walk into Güzelyalı | Still Walking (4K) No talking. No rush. Just walking. This uninterrupted walk begins in the back streets, slowly making its way into Güzelyalı. Along the way, the city reveals itself quietly — hidden corners, unexpected details, and a natural flow that leads, without effort, to the sea. This walk is not about reaching a place quickly, but about noticing what appears when you move slowly. 📍 Location: Güzelyalı, İzmir, Türkiye 🎥 Camera: DJI Osmo Pocket 3 🎞️ Mode: Normal 🎬 Resolution: 4K 🎧 Audio: Natural city sounds If this walk gave you a moment of calm, feel free to like, subscribe, or share it with someone who enjoys quiet exploration. Thanks for walking with me. Still walking. Explore all walking journeys here: 👉 https://www.youtube.com/playlist?list=PLe0tLqhfoJ0kA5DZ-hMOT5mX-rHSVN8EK Contact: izmirexplorer@gmail.com #StillWalking #Güzelyalı #Izmir #QuietWalk #WalkingTour #UrbanWalk #StreetWalk #NoTalking #CitySounds","thumbnail":"https://i.ytimg.com/vi/ctQMAcBZpEA/maxresdefault.jpg","category":"Walking Tours","city":"Izmir","country":"Turkey","channel":"Still Walking","channelTitle":"Still Walking","channelId":"UCD9clPtpOTsz7PPrm2JpafQ","badge":"4K 60FPS","publishedAt":"2026-02-05T15:01:10Z","viewCount":1688,"durationSeconds":3512,"admission":{"version":3,"status":"channel-candidate","source":"channel-archive","mode":"CITY"}}','1');
INSERT OR IGNORE INTO videos (id,title,description,thumbnail,category,channel,channel_title,channel_id,badge,published_at,city,country,raw_json,active) VALUES ('GHDMnxDitHI','The İzmir Tourists Never See: Backstreets, Boulevards & Concrete Maze | Türkiye 4K Walk','Welcome to a different side of Izmir. This 4K walking tour takes you far away from the city''s famous waterfront, tourist attractions, and postcard views. Instead, we explore the everyday urban landscape that most visitors never see. Our route begins in the residential backstreets of Eşrefpaşa, continues through busy city boulevards and side streets, and then descends into the dense concrete maze of Altıntaş. From there, we make our way toward the lower avenues and finally reach the Konak underpass area, revealing a raw and authentic side of city life in Izmir, Türkiye. This is not a tourist walk. There are no beaches, no historic landmarks, and no carefully curated travel experiences. Just ordinary neighborhoods, apartment blocks, local streets, summer heat, and the rhythm of everyday life. If you enjoy authentic urban exploration, real city environments, residential neighborhoods, and seeing places beyond the guidebooks, this walk offers a different perspective on Izmir. 📍 Route: Eşrefpaşa → Altıntaş → Konak Underpass ☀️ Weather: 35°C 🎥 4K 60fps Walking Tour 📍 İzmir, Türkiye still walking 👣 continue walking here: 👉https://www.youtube.com/playlist?list=PLe0tLqhfoJ0lD4ABpCnNmKAxMpHq607gz from an earlier time: 👉 https://www.youtube.com/playlist?list=PLe0tLqhfoJ0kA5DZ-hMOT5mX-rHSVN8EK Contact: izmirexplorer@gmail.com #Izmir #4KWalk #CityWalk #StreetLife #IzmirTurkey #TurkeyTravel #walkingtour','https://i.ytimg.com/vi/GHDMnxDitHI/maxresdefault.jpg','Walking Tours','Still Walking','Still Walking','UCD9clPtpOTsz7PPrm2JpafQ','4K 60FPS','2026-06-03T15:00:18Z','Izmir','Turkey','{"id":"GHDMnxDitHI","title":"The İzmir Tourists Never See: Backstreets, Boulevards & Concrete Maze | Türkiye 4K Walk","description":"Welcome to a different side of Izmir. This 4K walking tour takes you far away from the city''s famous waterfront, tourist attractions, and postcard views. Instead, we explore the everyday urban landscape that most visitors never see. Our route begins in the residential backstreets of Eşrefpaşa, continues through busy city boulevards and side streets, and then descends into the dense concrete maze of Altıntaş. From there, we make our way toward the lower avenues and finally reach the Konak underpass area, revealing a raw and authentic side of city life in Izmir, Türkiye. This is not a tourist walk. There are no beaches, no historic landmarks, and no carefully curated travel experiences. Just ordinary neighborhoods, apartment blocks, local streets, summer heat, and the rhythm of everyday life. If you enjoy authentic urban exploration, real city environments, residential neighborhoods, and seeing places beyond the guidebooks, this walk offers a different perspective on Izmir. 📍 Route: Eşrefpaşa → Altıntaş → Konak Underpass ☀️ Weather: 35°C 🎥 4K 60fps Walking Tour 📍 İzmir, Türkiye still walking 👣 continue walking here: 👉https://www.youtube.com/playlist?list=PLe0tLqhfoJ0lD4ABpCnNmKAxMpHq607gz from an earlier time: 👉 https://www.youtube.com/playlist?list=PLe0tLqhfoJ0kA5DZ-hMOT5mX-rHSVN8EK Contact: izmirexplorer@gmail.com #Izmir #4KWalk #CityWalk #StreetLife #IzmirTurkey #TurkeyTravel #walkingtour","thumbnail":"https://i.ytimg.com/vi/GHDMnxDitHI/maxresdefault.jpg","category":"Walking Tours","city":"Izmir","country":"Turkey","channel":"Still Walking","channelTitle":"Still Walking","channelId":"UCD9clPtpOTsz7PPrm2JpafQ","badge":"4K 60FPS","publishedAt":"2026-06-03T15:00:18Z","viewCount":1687,"durationSeconds":2525,"admission":{"version":3,"status":"channel-candidate","source":"channel-archive","mode":"CITY"}}','1');
INSERT OR IGNORE INTO videos (id,title,description,thumbnail,category,channel,channel_title,channel_id,badge,published_at,city,country,raw_json,active) VALUES ('rOKqU_JdCAQ','WALK WITH US! Poligon, Izmir 🇹🇷 See The Streets, You Score The Vibe (Neighborhood Review)','WALK WITH US! Welcome to our first-ever İzmir Neighborhood Review series. In this episode, we''re exploring Poligon, a peaceful and central neighborhood in İzmir. Izmir Neighborhood Review #1: Poligon (The Scorecard) This is a no-talk full walking tour designed to let you experience the atmosphere, sights, and sounds of Poligon, İzmir. We start right at the Poligon Metro Station and walk deep into the backstreets to reveal both the main avenues and the quiet, residential areas. What You Will See: Proximity to the Metro / Transport Links Local Amenities (Cafes, Markets, Shops) Residential Streets and Safety Vibe ⭐ YOUR MISSION: Score the Vibe! Since we don''t talk, we need your help! Watch the full walk, see the streets, and let us know your scores for Poligon in the comments below: Safety & Cleanliness: /5 Vibe & Atmosphere: /5 Transport & Amenities: /5 Don''t forget to subscribe for our next neighborhood review! 🎧 No talking — just natural sounds Izmir Walking Tour🚶‍♂️ Konak-Karabağlar District🏛️ Poligon Neighborhood 🏘️ Date: November 28, 2025 (Friday) 📅 Time: 2 PM 🕓 Temperature: 23°C 🌡️ Camera: Dji Osmo Pocket 3 🎥 All Izmir walking tours here: Real Izmir Walking Tours 4K 🇹🇷 https://www.youtube.com/playlist?list=PLe0tLqhfoJ0kA5DZ-hMOT5mX-rHSVN8EK Contact: izmirexplorer@gmail.com #izmir #poligon #izmirneighborhoods #walkingtours #neighborhoodrating #turkey #livinginizmir #izmirvlog','https://i.ytimg.com/vi/rOKqU_JdCAQ/maxresdefault.jpg','Walking Tours','Still Walking','Still Walking','UCD9clPtpOTsz7PPrm2JpafQ','4K 60FPS','2025-11-29T11:31:18Z','Izmir','Turkey','{"id":"rOKqU_JdCAQ","title":"WALK WITH US! Poligon, Izmir 🇹🇷 See The Streets, You Score The Vibe (Neighborhood Review)","description":"WALK WITH 