INSERT OR IGNORE INTO videos (id,title,description,thumbnail,category,channel,channel_title,channel_id,badge,published_at,city,country,raw_json,active) VALUES ('ebUX3xh2bTI','Walking from the Hills to the Sea in Izmir | Still Walking','A walk that started in the hills and slowly found its way to the sea. This walk begins in the hillside neighborhood of Basın Sitesi in Izmir. While heading down toward the city, unexpected stairs and hidden paths appear along the way — some of them with beautiful views of the Gulf. At one point the route changes completely. After reaching the lower streets, the walk climbs back up again toward Susuzdede Park to enjoy the panoramic view of Izmir. A short rest on a bench, a quiet moment overlooking the city… and then the journey continues through forest paths, streets and finally down to the coastline. Sometimes the best routes appear when you simply keep walking. Still Walking 👣 📍 Route: Basın Sitesi → Susuzdede Park → Göztepe Coast, Izmir – Türkiye ⏱ Real time – No talking – Natural city sounds This walk is part of the “No Plan” series. continue walking here: 👉https://www.youtube.com/playlist?list=PLe0tLqhfoJ0lD4ABpCnNmKAxMpHq607gz from an earlier time: 👉 https://www.youtube.com/playlist?list=PLe0tLqhfoJ0kA5DZ-hMOT5mX-rHSVN8EK Contact: izmirexplorer@gmail.com Titles in other languages EN Walking from the Hills to the Sea in Izmir | Still Walking TR İzmir Tepelerinden Denize Yürüyüş | Still Walking | Basın Sitesi – Göztepe ES Caminando desde las colinas hasta el mar en Izmir | Still Walking #Izmir #WalkingTour #StreetWalking #CityWalk #StillWalking #NoPlanWalk','https://i.ytimg.com/vi/ebUX3xh2bTI/maxresdefault.jpg','Walking Tours','Still Walking','Still Walking','UCD9clPtpOTsz7PPrm2JpafQ','4K 60FPS','2026-03-11T10:46:16Z','Izmir','Turkey','{"id":"ebUX3xh2bTI","title":"Walking from the Hills to the Sea in Izmir | Still Walking","description":"A walk that started in the hills and slowly found its way to the sea. This walk begins in the h