INSERT OR IGNORE INTO videos (id,title,description,thumbnail,category,channel,channel_title,channel_id,badge,published_at,city,country,raw_json,active) VALUES ('WY6fLvHhDno','Izmir Alsancak Walking Tour: Organic Market to Nostalgic Backstreets & Skyline Views 4K 🇹🇷','Join this peaceful 4K walking tour through the quiet, authentic side of Alsancak Izmir! 🇹🇷 Start at the lively organic market in the green park, full of fresh local produce and natural vibes. Then wander into calm, nostalgic backstreets with untouched historic homes and old architecture. The journey ends with the striking contrast of a brand new football stadium and rising modern skyline in the background. Experience Izmir''s perfect blend of past and future – relaxing, mindful, and rarely seen. Natural sounds only (no commentary) – perfect for ASMR relaxation or virtual travel! Filmed in stunning 4K. Izmir Walking Tour🚶‍♂️ Konak District🏛️ Date: November 5, 2025 (Wednesday) 📅 Time: 3 PM 🕓 Temperature: 25°C 🌡️ Camera: Dji Osmo Pocket 3 🎥 🎧 Pure ambient sounds! ✨ Loved it? LIKE 👍 SUBSCRIBE 🔔 & turn on notifications for more hidden Izmir walks! #AlsancakIzmir #IzmirWalkingTour #OrganicMarketIzmir #AlsancakBackstreets #IzmirLocalLife #IzmirSkyline #TurkeyWalkingTour #Izmir4K #AlsancakNostalgic #IzmirHiddenGems All Izmir walking tours here: Real Izmir Walking Tours 4K 🇹🇷 https://www.youtube.com/playlist?list=PLe0tLqhfoJ0kA5DZ-hMOT5mX-rHSVN8EK Contact: izmirexplorer@gmail.com','https://i.ytimg.com/vi/WY6fLvHhDno/maxresdefault.jpg','Walking Tours','Still Walking','Still Walking','UCD9clPtpOTsz7PPrm2JpafQ','4K 60FPS','2025-11-06T14:45:04Z','Izmir','Turkey','{"id":"WY6fLvHhDno","title":"Izmir Alsancak Walking Tour: Organic Market to Nostalgic Backstreets & Skyline Views 4K 🇹🇷","description":"Join this peaceful 4K walking tour through the quiet, authentic side of Alsancak Izmir! 🇹🇷 Start at the lively organic market in the green park, full of fresh local produce and natural vibes. Then wander into calm, nostalgic backstreets with untouched historic homes and old architecture. The journey ends with the striking contrast of a brand new football stadium and rising modern skyline in the background. Experience Izmir''s perfect blend of past and future – relaxing, mindful, and rarely seen. Natural sounds only (no commentary) – perfect for ASMR relaxation or virtual travel! Filmed in stunning 4K. Izmir Walking Tour🚶‍♂️ Konak District🏛️ Date: November 5, 2025 (Wednesday) 📅 Time: 3 PM 🕓 Temperature: 25°C 🌡️ Camera: Dji Osmo Pocket 3 🎥 🎧 Pure ambient sounds! ✨ Loved it? LIKE 👍 SUBSCRIBE 🔔 & turn on notifications for more hidden Izmir walks! #AlsancakIzmir #IzmirWalkingTour #OrganicMarketIzmir #AlsancakBackstreets #IzmirLocalLife #IzmirSkyline #TurkeyWalkingTour #Izmir4K #AlsancakNostalgic #IzmirHiddenGems All Izmir walking tours here: Real Izmir Walking Tours 4K 🇹🇷 https://www.youtube.com/playlist?list=PLe0tLqhfoJ0kA5DZ-hMOT5mX-rHSVN8EK Contact: izmirexplorer@gmail.com","thumbnail":"https://i.ytimg.com/vi/WY6fLvHhDno/maxresdefault.jpg","category":"Walking Tours","city":"Izmir","country":"Turkey","channel":"Still Walking","channelTitle":"Still Walking","channelId":"UCD9clPtpOTsz7PPrm2JpafQ","badge":"4K 60FPS","publishedAt":"2025-11-06T14:45:04Z","viewCount":1363,"durationSeconds":2142,"admission":{"version":3,"status":"channel-candidate","source":"channel-archive","mode":"CITY"}}','1');
INSERT OR IGNORE INTO videos (id,title,description,thumbnail,category,channel,channel_title,channel_id,badge,published_at,city,country,raw_json,active) VALUES ('IxHLtI3Pn0Y','Turkey: Living in Izmir''s Quietest Neighborhood | Explore Bornova Evka 3 (4K Walk) 👣','Turkey: Living in Izmir''s Quietest Neighborhood | Explore Bornova Evka 3 (4K Walk) 👣 starting above the city in Evka 3 and drifting downhill through winding streets, parks, and quiet neighborhoods toward the urban center. Starting high above Bornova, the walk moves between green streets, open roads, and narrower passages that appear unexpectedly along the way. Some streets feel wide and unhurried, others barely leave enough room to pass through. Without a fixed route, the walk gradually drifts downhill — occasional wrong turns, distant towers appearing between buildings, hidden villas further down the slope. The city unfolds at its own pace, revealing a quieter side of Izmir away from crowded areas. Filmed with natural sounds, no commentary, and long uninterrupted sequences capturing the slow rhythm of moving through everyday residential streets and changing city views. still walking 👣 📍 Evka 3 → Bornova, Izmir, Türkiye ⏱ real time – no talking – natural sound continue walking here: 👉https://www.youtube.com/playlist?list=PLe0tLqhfoJ0lD4ABpCnNmKAxMpHq607gz from an earlier time: 👉 https://www.youtube.com/playlist?list=PLe0tLqhfoJ0kA5DZ-hMOT5mX-rHSVN8EK Contact: izmirexplorer@gmail.com #izmir #bornova #walkingtour #streetwalk #turkey #stillwalking','https://i.ytimg.com/vi/IxHLtI3Pn0Y/maxresdefault.jpg','Walking Tours','Still Walking','Still Walking','UCD9clPtpOTsz7PPrm2JpafQ','4K 60FPS','2026-04-29T14:30:27Z','Izmir','Turkey','{"id":"IxHLtI3Pn0Y","title":"Turkey: Living in Izmir''s Quietest Neighborhood | Explore Bornova Evka 3 (4K Walk) 👣","description":"Turkey: Living in Izmir''s Quietest Neighborhood | Explore Bornova Evka 3 (4K Walk) 👣 starting above the city in Evka 3 and drifting downhill through winding streets, parks, and quiet neighborhoods toward the urban center. Starting high above Bornova, the walk moves between green streets, open roads, and narrower passages that appear unexpectedly along the way. Some streets feel wide and unhurried, others barely leave enough room to pass through. Without a fixed route, the walk gradually drifts downhill — occasional wrong turns, distant towers appearing between buildings, hidden villas further down the slope. The city unfolds at its own pace, revealing a quieter side of Izmir away from crowded areas. Filmed with natural sounds, no commentary, and long uninterrupted sequences capturing the slow rhythm of moving through everyday residential streets and changing city views. still walking 👣 📍 Evka 3 → Bornova, Izmir, Türkiye ⏱ real time – no talking – natural sound continue walking here: 👉https://www.youtube.com/playlist?list=PLe0tLqhfoJ0lD4ABpCnNmKAxMpHq607gz from an earlier time: 👉 https://www.youtube.com/playlist?list=PLe0tLqhfoJ0kA5DZ-hMOT5mX-rHSVN8EK Contact: izmirexplorer@gmail.com #izmir #bornova #walkingtour #streetwalk #turkey #stillwalking","thumbnail":"https://i.ytimg.com/vi/IxHLtI3Pn0Y/maxresdefault.jpg","category":"Walking Tours","city":"Izmir","country":"Turkey","channel":"Still Walking","channelTitle":"Still Walking","channelId":"UCD9clPtpOTsz7PPrm2JpafQ","badge":"4K 60FPS","publishedAt":"2026-04-29T14:30:27Z","viewCount":1336,"durationSeconds":4045,"admission":{"version":3,"status":"channel-candidate","source":"channel-archive","mode":"CITY"}}','1');
INSERT OR IGNORE INTO videos (id,title,description,thumbnail,category,channel,channel_title,channel_id,badge,published_at,city,country,raw_json,active) VALUES ('8AnrmsaOHw8','Walking Through the Textures of Kemeraltı, Izmir | Still Walking','A slow walk through the textures of Kemeraltı. Starting inside the metro station, the walk drifts through small details — analog clocks, turnstiles, old chairs, street cats, shop windows and worn walls. Instead of rushing through the crowd, the camera pauses for the small things that often go unnoticed: a street musician playing harmonica, cats calmly resting near their food bowls, modern lantern lights hanging above the streets, faded walls and everyday life unfolding in quiet corners. Kemeraltı reveals itself not through landmarks, but through its textures.. Still Walking 👣 📍 Location: Kemeraltı Bazaar, Izmir – Türkiye ⏱ Real time – No talking – Natural sound continue walking here: 👉https://www.youtube.com/playlist?list=PLe0tLqhfoJ0lD4ABpCnNmKAxMpHq607gz from an earlier time: 👉 https://www.youtube.com/playlist?list=PLe0tLqhfoJ0kA5DZ-hMOT5mX-rHSVN8EK Contact: izmirexplorer@gmail.com Titles in other languages EN Drifting Through the Textures of Kemeraltı, Izmir | Still Walking TR Kemeraltı’nın Dokuları Arasında Bir Yürüyüş | Still Walking ES Caminando entre las texturas de Kemeraltı, Izmir | Still Walking #Izmir #Kemeraltı #WalkingTour #StreetWalking #CityWalk #StillWalking','https://i.ytimg.com/vi/8AnrmsaOHw8/maxresdefault.jpg','Walking Tours','Still Walking','Still Walking','UCD9clPtpOTsz7PPrm2JpafQ','4K 60FPS','2026-03-14T10:00:13Z','Izmir','Turkey','{"id":"8AnrmsaOHw8","title":"Walking Through the Textures of Kemeraltı, Izmir | Still Walking","description":"A slow walk through the textures of Kemeraltı. Starting inside the metro station, the walk drifts through small details — analog clocks, turnstiles, old chairs, street cats, shop windows and worn walls. Instead of rushing through the crowd, the camera pauses for the small things that often go unnoticed: a street musician playing harmonica, cats calmly resting near their food bowls, modern lantern lights hanging above the streets, faded walls and everyday life unfolding in quiet corners. Kemeraltı reveals itself not through landmarks, but through its textures.. Still Walking 👣 📍 Location: Kemeraltı Bazaar, Izmir – Türkiye ⏱ Real time – No talking – Natural sound continue walking here: 👉https://www.youtube.com/playlist?list=PLe0tLqhfoJ0lD4ABpCnNmKAxMpHq607gz from an earlier time: 👉 https://www.youtube.com/playlist?list=PLe0tLqhfoJ0kA5DZ-hMOT5mX-rHSVN8EK Contact: izmirexplorer@gmail.com Titles in other languages EN Drifting Through the Textures of Kemeraltı, Izmir | Still Walking TR Kemeraltı’nın Dokuları Arasında Bir Yürüyüş | Still Walking ES Caminando entre las texturas de Kemeraltı, Izmir | Still Walking #Izmir #Kemeraltı #WalkingTour #StreetWalking #CityWalk #StillWalking","thumbnail":"https://i.ytimg.com/vi/8AnrmsaOHw8/maxresdefault.jpg","category":"Walking Tours","city":"Izmir","country":"Turkey","channel":"Still Walking","channelTitle":"Still Walking","channelId":"UCD9clPtpOTsz7PPrm2JpafQ","badge":"4K 60FPS","publishedAt":"2026-03-14T10:00:13Z","viewCount":1331,"durationSeconds":3807,"admission":{"version":3,"status":"channel-candidate","source":"channel-archive","mode":"CITY"}}','1');
INSERT OR IGNORE INTO videos (id,title,description,thumbnail,category,channel,channel_title,channel_id,badge,published_at,city,country,raw_json,active) VALUES ('nqqrzHT0VM4','The Most Hidden Neighborhood in the Heart of Izmir: Discover Kahramanlar | Turkey 4K Walk 👣','The Most Hidden Neighborhood in the Heart of Izmir: Discover Kahramanlar | Turkey 4K Walk 👣 A hidden sanctuary tucked away in the busiest part of the city—this is where the real İzmir breathes in silence. A walk through İzmir — where the city keeps changing its face with every turn. This journey begins on a bridge over the railway. Just as I descend the stairs to enter the neighborhood, a train passes by, marking the start of our transition into the heart of Kahramanlar. These relatively narrow streets hold a unique atmosphere, where the urgency of hospitals and the transience of hotels meet the deep-rooted stillness of a local residential neighborhood. On this 4K walk, there is no set plan. We simply follow the shifting rhythms of the city. One moment you are surrounded by the clinical energy of a medical district, and the next, you are drifting through a quiet alley that feels like a hidden sanctuary. This video is about those subtle transitions—between the rhythmic movement of the tracks and the sudden "openness" of the city’s hidden corners. Discover the authentic, unpolished soul of İzmir in a neighborhood that many pass through, but few truly see. Atmosphere: Urban contrast, rhythmic train sounds, and local neighborhood vibes. Route: Railway Bridge (Stairs), Hospital District, and the Backstreets of Kahramanlar. Experience: Long uninterrupted sequences, natural ambient sounds, no commentary. still walking 👣 Location: Izmir, Kahramanlar — Türkiye continue walking here: 👉https://www.youtube.com/playlist?list=PLe0tLqhfoJ0lD4ABpCnNmKAxMpHq607gz from an earlier time: 👉 https://www.youtube.com/playlist?list=PLe0tLqhfoJ0kA5DZ-hMOT5mX-rHSVN8EK Contact: izmirexplorer@gmail.com #izmir #citywalk #walkingtour #citywalk #turkeytravel','https://i.ytimg.com/vi/nqqrzHT0VM4/maxresdefault.jpg','Walking Tours','Still Walking','Still Walking','UCD9clPtpOTsz7PPrm2JpafQ','4K 60FPS','2026-04-01T14:30:34Z','Izmir','Turkey','{"id":"nqqrzHT0VM4","title":"The Most Hidden Neighborhood in the Heart of Izmir: Discover Kahramanlar | Turkey 4K Walk 👣","description":"The Most Hidden Neighborhood in the Heart of Izmir: Discover Kahramanlar | Turkey 4K Walk 👣 A hidden sanctuary tucked away in the busiest part of the city—this is where the real İzmir breathes in silence. A walk through İzmir — where the city keeps changing its face with every turn. This journey begins on a bridge over the railway. Just as I descend the stairs to enter the neighborhood, a train passes by, marking the start of our transition into the heart of Kahramanlar. These relatively narrow streets hold a unique atmosphere, where the urgency of hospitals and the transience of hotels meet the deep-rooted stillness of a local residential neighborhood. On this 4K walk, there is no set plan. We simply follow the shifting rhythms of the city. One moment you are surrounded by the clinical energy of a medical district, and the next, you are drifting through a quiet alley that feels like a hidden sanctuary. This video is about those subtle transitions—between the rhythmic movement of the tracks and the sudden \"openness\" of the city’s hidden corners. Discover the authentic, unpolished soul of İzmir in a neighborhood that many pass through, but few truly see. Atmosphere: Urban contrast, rhythmic train sounds, and local neighborhood vibes. Route: Railway Bridge (Stairs), Hospital District, and the Backstreets of Kahramanlar. Experience: Long uninterrupted sequences, natural ambient sounds, no commentary. still walking 👣 Location: Izmir, Kahramanlar — Türkiye continue walking here: 👉https://www.youtube.com/playlist?list=PLe0tLqhfoJ0lD4ABpCnNmKAxMpHq607gz from an earlier time: 👉 https://www.youtube.com/playlist?list=PLe0tLqhfoJ0kA5DZ-hMOT5mX-rHSVN8EK Contact: izmirexplorer@gmail.com #izmir #citywalk #walkingtour #citywalk #turkeytravel","thumbnail":"https://i.ytimg.com/vi/nqqrzHT0VM4/maxresdefault.jpg","category":"Walking Tours","city":"Izmir","country":"Turkey","channel":"Still Walking","channelTitle":"Still Walking","channelId":"UCD9clPtpOTsz7PPrm2JpafQ","badge":"4K 60FPS","publishedAt":"2026-04-01T14:30:34Z","viewCount":1318,"durationSeconds":3904,"admission":{"version":3,"status":"channel-candidate","source":"channel-archive","mode":"CITY"}}','1');
INSERT OR IGNORE INTO videos (id,title,description,thumbnail,category,channel,channel_title,channel_id,badge,published_at,city,country,raw_json,active) VALUES ('tuZS5fS-4vE','The Red Sea: Göztepe Fans Celebrate in Style | Turkey, Izmir Walking Tour (4K 60fps)','Göztepe fans were thrilled to celebrate the club''s 97th birthday. Izmir walking tour Konak District Göztepe neighborhood June 14, 2022 9 pm Tuesday Temperature: +32 ℃ #izmir #göztepe #walkingtour #turkey #türkiye #izmirexplorer The Red Sea: Göztepe Fans Celebrate in Style | Turkey, Izmir Walking Tour (4K 60fps) Göztepe Taraftarları Kutlama Yapıyor | 4K İzmir Turu - 14 Haziran 2022','https://i.ytimg.com/vi/tuZS5fS-4vE/maxresdefault.jpg','Walking Tours','Still Walking','Still Walking','UCD9clPtpOTsz7PPrm2JpafQ','4K 60FPS','2022-06-16T11:26:27Z','Izmir','Turkey','{"id":"tuZS5fS-4vE","title":"The Red Sea: Göztepe Fans Celebrate in Style | Turkey, Izmir Walking Tour (4K 60fps)","description":"Göztepe fans were thrilled to celebrate the club''s 97th birthday. Izmir walking tour Konak District Göztepe neighborhood June 14, 2022 9 pm Tuesday Temperature: +32 ℃ #izmir #göztepe #walkingtour #turkey #türkiye #izmirexplorer The Red Sea: Göztepe Fans Celebrate in Style | Turkey, Izmir Walking Tour (4K 60fps) Göztepe Taraftarları Kutlama Yapıyor | 4K İzmir Turu - 14 Haziran 2022","thumbnail":"https://i.ytimg.com/vi/tuZS5fS-4vE/maxresdefault.jpg","category":"Walking Tours","city":"Izmir","country":"Turkey","channel":"Still Walking","channelTitle":"Still Walking","channelId":"UCD9clPtpOTsz7PPrm2JpafQ","badge":"4K 60FPS","publishedAt":"2022-06-16T11:26:27Z","viewCount":1313,"durationSeconds":1996,"admission":{"version":3,"status":"channel-candidate","source":"channel-archive","mode":"CITY"}}','1');
INSERT OR IGNORE INTO videos (id,title,description,thumbnail,category,channel,channel_title,channel_id,badge,published_at,city,country,raw_json,active) VALUES ('n5q7QtZ_RLU','Real Local Walk in Izmir: The City Changes Every Few Minutes | Turkey 4K (Towards Historic Elevator)','This walk begins high above the city, descending through İzmir’s deeply layered neighborhoods. Starting from the rugged, authentic streets of Eşrefpaşa, we slowly make our way down toward the coast. This route takes you through a fascinating shift in atmosphere—from busy transit roads to quiet, maze-like backstreets and narrow stone stairways. After the rain, even a silent park becomes a sanctuary filled with the songs of birds and the fresh scent of wet pavement. As the elevation drops, the city’s face changes. We leave the gritty local charm behind and enter Karataş, one of İzmir’s oldest and most historic districts, eventually reaching the iconic Historic Elevator (Asansör) and the charming Dario Moreno Street. No rush. No narration. Just the natural rhythm of the city, the soft wind, and a slow, meditative descent toward sea level. 📍 Location: Eşrefpaşa - Karataş - Historic Elevator | İzmir, Türkiye 📅 Date: January 24, 2026 (Saturday) 🕓 Time: 3:00 PM 🌡️ Temperature: 13°C 🎧 Experience: 4K 60fps | Natural Sounds | Binaural Audio (ASMR) continue walking here: 👉https://www.youtube.com/playlist?list=PLe0tLqhfoJ0lD4ABpCnNmKAxMpHq607gz from an earlier time: 👉 https://www.youtube.com/playlist?list=PLe0tLqhfoJ0kA5DZ-hMOT5mX-rHSVN8EK Contact: izmirexplorer@gmail.com #izmir #walkingtour #turkeytravel #citywalk #karataş #stillwalking','https://i.ytimg.com/vi/n5q7QtZ_RLU/maxresdefault.jpg','Museums & Culture','Still Walking','Still Walking','UCD9clPtpOTsz7PPrm2JpafQ','4K 60FPS','2026-01-26T15:01:21Z','Izmir','Turkey','{"id":"n5q7QtZ_RLU","title":"Real Local Walk in Izmir: The City Changes Every Few Minutes | Turkey 4K (Towards Historic Elevator)","description":"This walk begins high above the city, descending through İzmir’s deeply layered neighborhoods. Starting from the rugged, authentic streets of Eşrefpaşa, we slowly make our way down toward the coast. This route takes you through a fascinating shift in atmosphere—from busy transit roads to quiet, maze-like backstreets and narrow stone stairways. After the rain, even a silent park becomes a sanctuary filled with the songs of birds and the fresh scent of wet pavement. As the elevation drops, the city’s face changes. We leave the gritty local charm behind and enter Karataş, one of İzmir’s oldest and most historic districts, eventually reaching the iconic Historic Elevator (Asansör) and the charming Dario Moreno Street. No rush. No narration. Just the natural rhythm of the city, the soft wind, and a slow, meditative descent toward sea level. 📍 Location: Eşrefpaşa - Karataş - Historic Elevator | İzmir, Türkiye 📅 Date: January 24, 2026 (Saturday) 🕓 Time: 3:00 PM 🌡️ Temperature: 13°C 🎧 Experience: 4K 60fps | Natural Sounds | Binaural Audio (ASMR) continue walking here: 👉https://www.youtube.com/playlist?list=PLe0tLqhfoJ0lD4ABpCnNmKAxMpHq607gz from an earlier time: 👉 https://www.youtube.com/playlist?list=PLe0tLqhfoJ0kA5DZ-hMOT5mX-rHSVN8EK Contact: izmirexplorer@gmail.com #izmir #walkingtour #turkeytravel #citywalk #karataş #stillwalking","thumbnail":"https://i.ytimg.com/vi/n5q7QtZ_RLU/maxresdefault.jpg","category":"Museums & Culture","city":"Izmir","country":"Turkey","channel":"Still Walking","channelTitle":"Still Walking","channelId":"UCD9clPtpOTsz7PPrm2JpafQ","badge":"4K 60FPS","publishedAt":"2026-01-26T15:01:21Z","viewCount":1308,"durationSeconds":2585,"admission":{"version":3,"status":"channel-candidate","source":"channel-archive","mode":"CITY"}}','1');
