INSERT OR IGNORE INTO videos (id,title,description,thumbnail,category,channel,channel_title,channel_id,badge,published_at,city,country,raw_json,active) VALUES ('vQiTbLuit1k','Plansız, Rotasız — İzmir’de Kayboldum | Still Walking','A walk with no map and no plan. This time I started in 📍 Halkapınar and kept walking until I had no idea where I was. Streets changed, the atmosphere shifted, and the city revealed itself step by step. This walk is part of the “No Map, No Plan” series — pure exploration, no route, no destination. 📍 Location: Halkapınar, İzmir,, Türkiye 🎥 Camera: DJI Osmo Pocket 3 🎬 Resolution: 4K 🎧 Audio: Natural city sounds If you enjoy walking without a destination, you’re always welcome here. 👣 Still Walking continue walking here: 👉https://www.youtube.com/playlist?list=PLe0tLqhfoJ0lD4ABpCnNmKAxMpHq607gz from an earlier time: 👉 https://www.youtube.com/playlist?list=PLe0tLqhfoJ0kA5DZ-hMOT5mX-rHSVN8EK Contact: izmirexplorer@gmail.com #StillWalking #NoMapNoPlan #LostInIzmir #WalkingTour #CityWalk #UrbanExploration #4KWalk #NoMusic #ASMRWalk','https://i.ytimg.com/vi/vQiTbLuit1k/maxresdefault.jpg','Walking Tours','Still Walking','Still Walking','UCD9clPtpOTsz7PPrm2JpafQ','4K 60FPS','2026-02-27T08:20:44Z','Izmir','Turkey','{"id":"vQiTbLuit1k","title":"Plansız, Rotasız — İzmir’de Kayboldum | Still Walking","description":"A walk with no map and no plan. This time I started in 📍 Halkapınar and kept walking until I had no idea where I was. Streets changed, the atmosphere shifted, and the city revealed itself step by step. This walk is part of the “No Map, No Plan” series — pure exploration, no route, no destination. 📍 Location: Halkapınar, İzmir,, Türkiye 🎥 Camera: DJI Osmo Pocket 3 🎬 Resolution: 4K 🎧 Audio: Natural city sounds If you enjoy walking without a destination, you’re always welcome here. 👣 Still Walking continue walking here: 👉https://www.youtube.com/playlist?list=PLe0tLqhfoJ0lD4ABpCnNmKAxMpHq607gz from an earlier time: 👉 https://www.youtube.com/playlist?list=PLe0tLqhfoJ0kA5DZ-hMOT5mX-rHSVN8EK Contact: izmirexplorer@gmail.com #StillWalking #NoMapNoPlan #LostInIzmir #WalkingTour #CityWalk #UrbanExploration #4KWalk #NoMusic #ASMRWalk","thumbnail":"https://i.ytimg.com/vi/vQiTbLuit1k/maxresdefault.jpg","category":"Walking Tours","city":"Izmir","country":"Turkey","channel":"Still Walking","channelTitle":"Still Walking","channelId":"UCD9clPtpOTsz7PPrm2JpafQ","badge":"4K 60FPS","publishedAt":"2026-02-27T08:20:44Z","viewCount":1063,"durationSeconds":3389,"admission":{"version":3,"status":"channel-candidate","source":"channel-archive","mode":"CITY"}}','1');
INSERT OR IGNORE INTO videos (id,title,description,thumbnail,category,channel,channel_title,channel_id,badge,published_at,city,country,raw_json,active) VALUES ('OsVMdnXu51s','Still Walking Down Hatay | Streets, Silence & the Coastal Edge (4K)','This slow walk follows a gentle descent from İzmir’s Hatay district — through busy streets, quiet neighborhoods, and forgotten buildings, ending at the coastal boulevard. We begin on narrow stairways overlooking the lower parts of the city, move through colorful streets filled with daily life, and slowly drift into backstreets, parks, and abandoned mansions waiting in silence. Along the way, small moments appear — a crow on a dry tree, a cat lost in play, traces of life between decay and movement. The walk reaches the coastal boulevard, where the city meets the sea — but stays on the street side, leaving the shoreline for another walk. No talking. Just footsteps, wind, traffic, and the natural rhythm of İzmir. 📍 Location: İzmir Hatay, Turkey 📅 Date: January 19, 2026 (Monday) 🕓 Time: 3:00 PM 🌡️ Temperature: 6°C 🎥 Camera: DJI Osmo Pocket 3 🎞️ Mode: Normal 🎬 Resolution: 4K 🎧 Audio: Natural city sounds This walk is part of the Still Walking series — slow, uninterrupted walks guided only by the street itself. If this walk gave you a moment of calm, feel free to like, subscribe, or share it with someone who enjoys quiet exploration. Thanks for walking with me. Still walking. Explore all walking journeys here: 👉 https://www.youtube.com/playlist?list=PLe0tLqhfoJ0kA5DZ-hMOT5mX-rHSVN8EK Contact: izmirexplorer@gmail.com #stillwalking #Izmir #WalkingTour #SlowWalk #HiddenStreets #NoTalkingWalk','https://i.ytimg.com/vi/OsVMdnXu51s/maxresdefault.jpg','Beach Walking Tours','Still Walking','Still Walking','UCD9clPtpOTsz7PPrm2JpafQ','4K 60FPS','2026-01-20T18:00:33Z','Izmir','Turkey','{"id":"OsVMdnXu51s","title":"Still Walking Down Hatay | Streets, Silence & the Coastal Edge (4K)","description":"This slow walk follows a gentle descent from İzmir’s Hatay district — through busy streets, quiet neighborhoods, and forgotten buildings, ending at the coastal boulevard. We begin on narrow stairways overlooking the lower parts of the city, move through colorful streets filled with daily life, and slowly drift into backstreets, parks, and abandoned mansions waiting in silence. Along the way, small moments appear — a crow on a dry tree, a cat lost in play, traces of life between decay and movement. The walk reaches the coastal boulevard, where the city meets the sea — but stays on the street side, leaving the shoreline for another walk. No talking. Just footsteps, wind, traffic, and the natural rhythm of İzmir. 📍 Location: İzmir Hatay, Turkey 📅 Date: January 19, 2026 (Monday) 🕓 Time: 3:00 PM 🌡️ Temperature: 6°C 🎥 Camera: DJI Osmo Pocket 3 🎞️ Mode: Normal 🎬 Resolution: 4K 🎧 Audio: Natural city sounds This walk is part of the Still Walking series — slow, uninterrupted walks guided only by the street itself. If this walk gave you a moment of calm, feel free to like, subscribe, or share it with someone who enjoys quiet exploration. Thanks for walking with me. Still walking. Explore all walking journeys here: 👉 https://www.youtube.com/playlist?list=PLe0tLqhfoJ0kA5DZ-hMOT5mX-rHSVN8EK Contact: izmirexplorer@gmail.com #stillwalking #Izmir #WalkingTour #SlowWalk #HiddenStreets #NoTalkingWalk","thumbnail":"https://i.ytimg.com/vi/OsVMdnXu51s/maxresdefault.jpg","category":"Beach Walking Tours","city":"Izmir","country":"Turkey","channel":"Still Walking","channelTitle":"Still Walking","channelId":"UCD9clPtpOTsz7PPrm2JpafQ","badge":"4K 60FPS","publishedAt":"2026-01-20T18:00:33Z","viewCount":990,"durationSeconds":3779,"admission":{"version":3,"status":"channel-candidate","source":"channel-archive","mode":"CITY"}}','1');
INSERT OR IGNORE INTO videos (id,title,description,thumbnail,category,channel,channel_title,channel_id,badge,published_at,city,country,raw_json,active) VALUES ('O7_K7ceg2g4','Explore Sığacık, İzmir in 4K: A Walking Tour of a Charming Turkish Town | Izmir Travel Guide','Explore Sığacık, İzmir in 4K: A Walking Tour of a Charming Turkish Town. Sığacık is a must-see destination for any visitor to İzmir, located in the Seferihisar district of İzmir. You will have a great time wandering through Sığacık''s stunning picturesque streets. Enjoy this wonderful walking tour. Have a nice day everyone. Contact: izmirexplorer@gmail.com #izmir #turkey #walkingtour #sığacık #turkeytravel','https://i.ytimg.com/vi/O7_K7ceg2g4/maxresdefault.jpg','Documentaries','Still Walking','Still Walking','UCD9clPtpOTsz7PPrm2JpafQ','4K 60FPS','2023-10-03T15:49:07Z','Izmir','Turkey','{"id":"O7_K7ceg2g4","title":"Explore Sığacık, İzmir in 4K: A Walking Tour of a Charming Turkish Town | Izmir Travel Guide","description":"Explore Sığacık, İzmir in 4K: A Walking Tour of a Charming Turkish Town. Sığacık is a must-see destination for any visitor to İzmir, located in the Seferihisar district of İzmir. You will have a great time wandering through Sığacık''s stunning picturesque streets. Enjoy this wonderful walking tour. Have a nice day everyone. Contact: izmirexplorer@gmail.com #izmir #turkey #walkingtour #sığacık #turkeytravel","thumbnail":"https://i.ytimg.com/vi/O7_K7ceg2g4/maxresdefault.jpg","category":"Documentaries","city":"Izmir","country":"Turkey","channel":"Still Walking","channelTitle":"Still Walking","channelId":"UCD9clPtpOTsz7PPrm2JpafQ","badge":"4K 60FPS","publishedAt":"2023-10-03T15:49:07Z","viewCount":941,"durationSeconds":2041,"admission":{"version":3,"status":"channel-candidate","source":"channel-archive","mode":"CITY"}}','1');
INSERT OR IGNORE INTO videos (id,title,description,thumbnail,category,channel,channel_title,channel_id,badge,published_at,city,country,raw_json,active) VALUES ('oRgCnLkq1jU','Descending İzmir''s Buca: Panoramic Hillside Walk to the Great Statue — still walking 4K 🇹🇷','Descending İzmir''s Buca: Panoramic Hillside Walk to the Great Statue — still walking No plan. No map. Just walking. This İzmir walking tour begins in the high-altitude neighborhood of Evka 1, where the journey is guided only by the light and the natural flow of the streets. Moving downhill through the quiet, residential backstreets, the city slowly reveals its face one layer at a time. Every detail is part of the story: a crow calling from a nearby tree, a long-distance zoom on a landmark, or a sudden change in the urban rhythm. On this 4K walk, we discover a vast park that breaks the city’s density, featuring a bridge with striking architecture at its heart. A distant figure becomes a destination. From high above, the Great Statue appears on the horizon, acting as a compass for the rest of the journey. What starts as a zoom from afar turns into a path toward a reward—a final destination that feels like a true prize after the descent. This is not about where I go. It’s about what the walk becomes. Atmosphere: Natural sounds, no commentary. Experience: Long uninterrupted sequences. Route: Evka 1, Hidden Parks, and the Mevlana Statue area. still walking 👣 📍 Location: Buca, İzmir – Türkiye ⏱ Real time – No talking – Natural sound continue walking here: 👉https://www.youtube.com/playlist?list=PLe0tLqhfoJ0lD4ABpCnNmKAxMpHq607gz from an earlier time: 👉 https://www.youtube.com/playlist?list=PLe0tLqhfoJ0kA5DZ-hMOT5mX-rHSVN8EK Contact: izmirexplorer@gmail.com #stillwalking #izmir #citywalk #buca #walkingtour','https://i.ytimg.com/vi/oRgCnLkq1jU/maxresdefault.jpg','Walking Tours','Still Walking','Still Walking','UCD9clPtpOTsz7PPrm2JpafQ','4K 60FPS','2026-03-04T08:30:01Z','Izmir','Turkey','{"id":"oRgCnLkq1jU","ti